programs.sol:
"""Approximate a surface-spelling detector, not a programming-topic detector.

Respond to short vowel-plus-de fragments and their inflections, mode/node/code,
selected words rhyming with made, and make/making forms. Case and leading
punctuation or spaces adjust the strength. Unmatched tokens get zero.
This token-local rule omits context effects and weaker, rarer lexical responses.
"""
import re

READS = ()

VOWEL_DE = {'a': 4.4, 'o': 3.3, 'u': 2.3, 'i': 0.95, 'e': 1.25}
MADE_RHYMES = {
    'made', 'trade', 'grade', 'shade', 'fade', 'wade', 'jade',
    'parade', 'arcade', 'decade',
}
# Inflected fragments of the same vowel-d spelling.
FRAGMENT_ENDINGS = {
    '': 1.0, 's': 0.70, 'd': 0.45, 'r': 0.30, 'n': 0.20,
    'rs': 0.30,
}


def response(token):
    word = token.strip().lstrip('._-/=([{,\"\'')
    lower = word.lower()
    capital = word[:1].isupper()
    if lower in {'make', 'makes', 'making'}:
        return 0.85 if capital else 0.95
    if lower in {'mode', 'modes'}:
        value = 4.6 if word == 'Mode' and token == word else 3.7
        return value * (0.8 if lower.endswith('s') else 1.0)
    if lower in {'node', 'nodes'} or word.startswith(('Node', 'node')):
        value = 2.8 if word.isupper() else (2.3 if capital else 2.7)
        if token.startswith(' '):
            value = 2.2
        elif token.startswith('.'):
            value = 3.4 if lower == 'nodes' else 2.9
        elif token.startswith('/'):
            value = 4.0
        elif token.startswith(('(', '[')):
            value = 1.8
        if lower == 'nodes' and not token.startswith('.'):
            value *= 0.8
        if len(lower) > 5:
            value *= 0.55 if token.startswith('.') else 1.0
        return value
    if lower in {'code', 'codes'}:
        return 1.8 if word.isupper() else (1.45 if capital else 1.25)
    if lower in {'coding', 'decode'}:
        return 0.85
    singular = lower[:-1] if lower.endswith('s') else lower
    if singular in MADE_RHYMES:
        if singular == 'trade':
            value = 2.5
        elif singular == 'grade':
            value = 2.4 if capital else 1.8
        elif singular in {'wade', 'jade', 'arcade'}:
            value = 2.7
        elif singular == 'decade':
            value = 1.0
        else:
            value = 1.85
        if capital and singular == 'made':
            value = 2.35
        return value * (0.8 if lower.endswith('s') else 1.0)
    if lower == 'trading':
        return 2.3
    if lower in {'traded', 'trader', 'traders'}:
        return 1.7
    if lower.startswith('adequ'):
        return 1.25
    if lower in {'academy', 'academies'}:
        return 0.85
    if lower == 'de':
        if word == 'DE':
            return 0.8 if token.startswith(' ') else 2.2
        if capital:
            return 0.6
        if token.startswith(' '):
            return 0.08
        return 1.3
    fragment = re.fullmatch('([aeiou])de(s|d|r|rs|n)?', lower)
    if fragment:
        vowel, ending = fragment.groups()
        if lower == 'oder':
            return 0.2
        value = VOWEL_DE[vowel] * FRAGMENT_ENDINGS[ending or '']
        if token.startswith(' ') and vowel in 'ao':
            value *= 0.7
        return value
    fragment = re.fullmatch('([aoieu])ding', lower)
    if fragment:
        return VOWEL_DE[fragment[1]] * 0.5
    if lower in {'rade', 'cade', 'iode'}:
        return 2.0 if token.startswith(' ') else 3.5
    if re.fullmatch('[aeiou]?[nlr]de', lower):
        if 'l' in lower:
            return 0.65
        return 1.5 if lower[0] in 'ioa' else 0.75
    if lower in {'riding', 'ride', 'rides', 'rider'}:
        return 0.9
    if lower in {'rode', 'rude'}:
        return 1.2
    return 0.0


def step(carry, prefix, upstream):
    return None, float(response(prefix.token_strings[-1]))

"""Approximate a detector of hexadecimal-letter continuations of numbers.

It responds to a--f / A--F after digits (including labels like 3D), using the
first letter's hex value, case, fragment length, and preceding hex-run length.
Literal markers boost responses; a few common byte-escape prefixes have their
own strengths. Some algebraic contexts are attenuated. Other text is mostly
silent. A bounded recent-text carry resets at each document boundary.
"""
import re

READS = ()
HEX = frozenset('abcdefABCDEF')
DIGITS = '0123456789'


def response(token, before):
    digit = bool(before and before[-1] in DIGITS)
    if token in ('\\xa', '\\xc', '\\xe'):
        return {'\\xa': 1.8, '\\xc': 0.7 if digit else 0.3,
                '\\xe': 0.95 if digit else 0.15}[token]
    prefixed = token.startswith('x') and before.endswith('0')
    letters = token[1:] if prefixed else token
    if not letters or not all(c in HEX for c in letters):
        return 0.0
    lower = letters.islower()
    rank = int(letters[0], 16) - 10
    extra = min(len(letters) - 1, 2)
    run = re.search(r'[0-9a-fA-F]+\Z', before)
    run = run[0] if run else ''
    marker = re.search(r'(0x|\\[xu]|#|%)[0-9a-fA-F]*\Z', before)
    marker = marker[1] if marker else ''
    value = (0.05 if lower else 0.1) if extra else 0.0
    if digit:
        value = (0.45 + 0.3 * rank + 0.65 * extra if lower else
                 0.6 + 0.1 * rank + 0.3 * extra)
        value += 0.12 * min(len(run), 10)
        if any(c in 'abcdef' for c in run):
            value += 0.3
        if marker or prefixed:
            value += 1.0 if lower else 0.8
        if marker == '%' and not lower:
            value += 1.6
        if not marker and not any(c in HEX for c in run):
            if re.search(r'\\frac|\^|[abc]²', before[-80:]):
                value -= 0.4
    elif run and any(c in DIGITS for c in run):
        value = 1.0 + 0.2 * rank + 0.2 * extra
    elif marker:
        value = 0.7 + 0.5 * extra
        if marker == '%' and not lower:
            value += 1.6
        elif marker == '%' and lower:
            value = {'d': 1.2, 'e': 1.3, 'f': 1.8, 'c': 1.5}.get(letters, 0.9)
        elif marker == '0x' and run:
            value += 0.8 + 0.15 * rank
    if len(letters) > 3:
        value *= 0.55
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, (before + token)[-160:]), float(response(token, before))

programs.haiku:
"""Hex-run detector: a hex letter (a-f) that continues a hexadecimal string already holding a digit."""
READS = ()

HEX = set("0123456789abcdefABCDEF")
LETTERS = set("abcdefABCDEF")

def hex_part(s):
    if s.startswith("\\x"):
        return s[2:]
    if s.startswith("x"):
        return s[1:]
    return s

def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = hex_part(toks[-1])
    if not cur or not all(c in LETTERS for c in cur):
        return None, 0.0
    run, has_digit = 0, False
    for i in range(len(toks) - 2, -1, -1):
        s = hex_part(toks[i])
        if not s or not all(c in HEX for c in s) or prefix.document_ids[i] != prefix.document_ids[-1]:
            break
        run += len(s)
        has_digit = has_digit or any(c.isdigit() for c in s)
    if not has_digit:
        return None, 0.0
    strength = 0.9 + 0.22 * min(run, 10)
    return None, strength * (0.8 + 0.07 * (int(cur[-1], 16) - 10))

programs.luna:
"""Mark letters that are part of mixed letter-and-digit strings or codes."""
READS = ()


def step(carry, prefix, upstream):
    t = prefix.position
    doc = prefix.document_ids[t]
    in_run, run_has_digit, last_was_digit, old_doc = carry or (False, False, False, doc)
    if old_doc != doc:
        in_run, run_has_digit, last_was_digit = False, False, False

    value = 0.0
    for char in prefix.token_strings[t]:
        if char.isascii() and char.isalnum():
            if not in_run:
                in_run, run_has_digit = True, False
            if char.isalpha() and run_has_digit:
                value = 0.85 if last_was_digit else 0.45
            if char.isdigit():
                run_has_digit = True
            last_was_digit = char.isdigit()
        else:
            in_run, run_has_digit, last_was_digit = False, False, False
    return (in_run, run_has_digit, last_was_digit, doc), value

"""Approximate a feature for waiting and public-facing places.

Waiting, transit, seating, and customer-service words are strong positive
cues. Recipe and ingredient words tend to pull the activation the other way.
"""

READS = ()

WAITING = {
    "wait", "waits", "waiting", "waited", "waiter", "waiters",
}
OTHER_WAITING = {
    "await", "awaiting", "queue", "queued", "queueing", "queues",
    "waitlist", "排队", "待",
}
TRANSIT = {
    "station", "stations", "railway", "platform", "terminal", "stop",
    "transit", "subway", "metro", "bus", "train", "passenger",
    "passengers", "parking", "站", "站在", "车站",
}
STRONG_HOSPITALITY = {
    "seat", "seats", "booth", "tray", "mirror", "coffee", "tea",
}
PUBLIC_PLACES = {
    "booth", "counter", "window", "restroom", "bathroom", "toilet",
    "cafeteria", "restaurant", "restaurants", "cafe", "bar", "seating",
    "seat", "seats", "lobby", "corridor", "dining", "room", "door",
    "stairs", "elevator", "mirror", "stand", "tray", "table", "tables",
    "chair", "outside", "inside", "餐厅", "お店",
}
SERVICE_PEOPLE = {
    "customer", "customers", "staff", "guest", "guests", "patron",
    "patrons", "server", "servers", "sitting", "stood", "standing",
    "walk", "walking", "arrive", "arrival", "客", "お客様", "スタッフ",
}
HOME_COOKING = {
    "recipe", "recipes", "ingredient", "ingredients", "appliance",
    "appliances", "baking",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower().strip(".,!?;:'\"()[]{}")
    if word in WAITING:
        return None, 0.95 if word != "waiting" else 1.2
    if word in OTHER_WAITING:
        return None, 0.4
    if word in TRANSIT:
        return None, 0.55
    if word in STRONG_HOSPITALITY:
        return None, 0.6
    if word in PUBLIC_PLACES or word in SERVICE_PEOPLE:
        return None, 0.38
    if word in HOME_COOKING:
        return None, -0.25
    return None, 0.0025

programs.sol:
"""Detect line layout, especially low-content line endings.

A newline token at the start of a line has a large response, especially if it
contains indentation, a comment marker, or a blank diff line. Earlier tokens
on the same line suppress the response. Indentation and comment-only lines
retain some response, including behind diff or source-line-number margins.
Ordinary text lines mostly do not. Long punctuation rules and page breaks
are related boundaries. Small responses also mark individual line-prefix
glyphs: indentation, diff/comment signs, braces, and table bars. All state
resets per document.
"""

READS = ()


def ending(token):
    """Classify the material bundled into a newline token."""
    head = token.split('\n', 1)[0].rstrip('\r')
    marks = head.strip()
    if not marks:
        size = 4.4 if '\t' in head else 3.4 if head else 2.0
        return 'blank', size
    if set(marks) <= {'+'}:
        return 'diff', 4.9
    if set(marks) <= {'-'}:
        return 'rule', 3.2 if len(marks) < 3 else 2.1
    if set(marks) <= {'*', '/', '#', '!'}:
        if '*' in marks and '/' in marks:
            return 'comment', 2.1 if marks == '/*' else 1.4
        return 'comment', 4.0
    if marks[0] in ')}]':
        return 'close', 0.6 if marks.endswith(',') else 1.5
    if marks[0] in '({[':
        return 'open', 1.7 if marks[0] == '{' else 3.0
    if set(marks) <= {'"', "'", '`'}:
        return 'quote', 2.7 if len(marks) == 1 else 1.3
    if len(marks) > 2 and set(marks) <= {'_', '-', '='}:
        return 'rule', 2.1
    if marks in {'>', '=', '&'}:
        return 'other', 3.0
    return 'other', 1.9


def separator(text):
    text = text.strip()
    return len(text) >= 16 and set(text) <= set('-=*_/#')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        line, count = '', 0
    else:
        _, line, count = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if token == '|':
        value = 0.32 if not line else -0.11
    elif not line:
        if token == '+':
            value = -0.55
        elif token == '\t':
            value = -0.18
        elif token in {'//', '{', '}'}:
            value = -0.27
    if separator(token) and not line.strip():
        value = -min(1.4, 0.015 * len(token.strip()))
    if '\f' in token:
        value = -1.85
    elif token == '\r':
        value = -1.3 if not line.strip('\r') else 0.0
    elif '\n' in token:
        kind, strength = ending(token)
        if not line:
            value = -strength
        elif (not line.strip() or line.strip() in {'+', '-'}
              or ('\t' in line and line.strip().lstrip('+-').isdigit())):
            # Indentation, diff signs, and printed source line numbers are margins.
            if kind == 'close':
                factor = 0.17 if token.startswith(' ') else 0.27
            else:
                factor = 0.72 if kind == 'comment' else 0.4
            attenuation = 1 + 0.3 * count if line.strip() else 1
            value = -factor * strength / attenuation
        elif separator(line) and count <= 1:
            value = -1.2
        elif count <= 1:
            head = token.split('\n', 1)[0].strip()
            if head:
                value = -0.25
            else:
                value = -0.65 if len(line) <= 5 else -0.4
                if len(line) >= 14:
                    value = -0.15
        elif count <= 3:
            value = -0.1 if count == 2 else -0.05
        interior_lines = token.split('\n')[1:-1]
        if any(s.strip('\r') and not s.strip() for s in interior_lines):
            value = min(value, -1.2)
    if '\n' in token:
        line = token.rsplit('\n', 1)[-1]
        count = int(bool(line))
    elif token in {'\r', '\f'}:
        line, count = '', 0
    else:
        line = (line + token)[-200:]
        count += int(bool(token.strip()))
    return (doc, line, count), value

programs.haiku:
"""Candidate 5: a line break that ends a line holding only punctuation or indentation
(no words). Indentation-only lines are strongly negative (tabs most), so are lines that
are a comment/banner/operator symbol; closing brackets and semicolons are only weakly so;
lines with any word are zero."""
import re

READS = ()

WORD = re.compile(r"\w")
CLOSERS = set(")]};,")
STRONG = set("/#+=-*(<>&'[")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if not tok.endswith("\n"):
        return carry, 0.0
    body = tok.rstrip("\r\n")
    # the text of this line before the newline token
    line = ""
    for s in reversed(prefix.token_strings[:-1]):
        if "\n" in s:
            line = s.split("\n")[-1] + line
            break
        line = s + line
    if WORD.search(line + body):
        return carry, 0.0
    sym = body.strip()
    if sym == "":
        if "\t" in body:
            return carry, -4.0
        return carry, -2.8 if body else -1.0
    if set(sym) <= CLOSERS:
        return carry, -0.7
    if set(sym) & STRONG:
        return carry, -2.3
    return carry, -1.1

programs.luna:
"""Mark curly-brace line endings and deeply indented blank lines.

These line endings tend to receive a negative pulse; ordinary line breaks
are left at zero. The prediction is deliberately shrunk because the cue is
only a rough guess at the component's activation.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[3] != doc:
        has_text, indent, last = False, 0, ""
    else:
        has_text, indent, last, _ = carry

    value = 0.0
    i = 0
    while i < len(token):
        char = token[i]
        if char == "\r" or char == "\n":
            if char == "\r" and i + 1 < len(token) and token[i + 1] == "\n":
                i += 1
            if not has_text and indent >= 3:
                value -= 1.0 + 0.4 * min(indent, 8)
            elif has_text and last == "{":
                value -= 1.8
            elif has_text and last == "}":
                value -= 0.6
            has_text, indent, last = False, 0, ""
        elif not has_text and char in " \t":
            indent += 8 if char == "\t" else 1
        elif not char.isspace():
            has_text, last = True, char
        i += 1

    return (has_text, indent, last, doc), float(0.5 * value)

programs.sol:
"""A token-level cue for staying, inhabiting, and holding on.

住 is a particularly strong cue; compounds retain smaller, form-specific
responses. English staying/residence and remain/retain/remember words evoke
weaker responses, as do a few other languages' corresponding forms.
Continue-family words have a small negative response.
Recent Japanese kana lower the prediction for standalone 住. This lexical
approximation leaves other tokens at zero, omitting weak background activity.
"""

READS = ()

# CJK residence and durative/holding forms, grouped by response strength.
CJK_CUES = (
    ({'住了'}, 4.8),
    ({'不住', '留住', '得住'}, 4.1),
    ({'抓住', '住在'}, 3.1),
    ({'住所', '保住'}, 2.5),
    ({'居住', '家住', '握住', '挡住'}, 2.2),
    ({'住房', '住宿', '入住', '记住', '抱住'}, 1.8),
    ({'住宅', '住院', '忍不住', '住户'}, 1.3),
    ({'牢记', '停留', '不留', '紧紧', '抓紧'}, 1.0),
    ({'停车', '不动', '扎根', '久久', '留下', '留在'}, 0.75),
    ({'留', '紧', '押', '公寓', '寓', '宿', '呆', '記得'}, 0.6),
    ({'久', '持久', '长久', '永远', '永久', '居民'}, 0.4),
)
STAY = {'stay', 'stays', 'stayed', 'staying'}
RESIDENT = {
    'resident', 'residents', 'residential', 'reside', 'resides',
    'residing', 'residency',
}
REMAIN_RETAIN = {
    'remain', 'remains', 'remained', 'retain', 'retains', 'retaining',
    'dwell', 'dwelling', 'parked',
}
REMEMBER = {'remember', 'remembers', 'remembered', 'remembering'}
HOLD_FAST = {
    'grab', 'grabs', 'grabbed', 'grabbing', 'grips', 'gripping',
    'arrest', 'arrested',
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    recent_kana = 0 if carry is None or carry[0] != doc else carry[1] - 1
    if any('\u3040' <= ch <= '\u30ff' for ch in token):
        recent_kana = 40
    recent_kana = max(0, recent_kana)
    word = token.strip()
    lower = word.lower()
    value = 0.0
    if word == '住':
        value = 5.65 if recent_kana else 6.4
    elif '住' in word:
        value = next((v for words, v in CJK_CUES if word in words), 2.1)
    elif word in {'驻', '駐'}:
        value = 2.9 if word == '驻' else 2.2
    elif lower in STAY:
        value = 1.24 if lower in {'stay', 'stays'} else 1.1
        if word[0].isupper():
            value = 1.0
        elif token == word:
            value *= 0.65
    elif lower in {'residence', 'residences'}:
        value = 0.95 if word[0].islower() else 0.65
    elif lower in RESIDENT:
        value = 0.5
    elif lower in REMAIN_RETAIN or lower in REMEMBER:
        value = 0.4
    elif lower == 'retention':
        value = 0.56
    elif lower == 'retained':
        value = 0.2
    elif lower in {'memorable', 'unforgettable', 'linger'}:
        value = 0.6
    elif lower in HOLD_FAST:
        value = 0.5
    elif lower in {'apartment', 'apartments'}:
        value = 0.4
    elif lower in {'continue', 'continues', 'continued', 'continuing'}:
        value = -0.16
    elif word == '주':  # Korean residence-related syllable, also other uses.
        value = 0.9 if token.startswith(' ') else 0.7
    elif word == 'ở' and token.startswith(' '):  # Vietnamese stay / at / in.
        value = 1.05
    elif word in {'trụ', 'giữ'} and token.startswith(' '):
        value = 0.7  # Vietnamese remain / hold.
    elif word in {'прож', 'Wohn'} and token.startswith(' '):
        value = 0.5  # Russian/German dwelling stems.
    else:
        value = next((v for words, v in CJK_CUES if word in words), 0.0)
    return (doc, recent_kana), value

programs.haiku:
"""Words for staying, living in, remaining, and holding on to something.

The component fires on the Chinese character 住 (live in, stay, hold on), most strongly as a
verb meaning stay or hold fast, and on its relatives 驻 (station) and 留住 (keep). It also
fires on English stay / reside / residence / remain / retain / remember and a few
cognates (Korean 주, Vietnamese ở, trụ). Near zero on other tokens.
"""
READS = ()

# Chinese: 住 and compounds. As a verb of staying or holding fast (住了, 不住, 抓住, 留住)
# it is strongest; as a noun of dwelling (住房, 住宅, 住宿) it is weaker.
ZHU_VERB = 4.0
ZHU_NOUN = 1.6
DWELL_NOUNS = ("住房", "住宅", "住宿", "住所", "住户", "住院")
STATION = {"驻": 2.2, "駐": 2.2, "留": 0.5, "宿": 0.6}

STAY = {"stay", "stays", "stayed", "staying"}
RESIDE = {"reside", "resides", "residing", "residence", "residences", "resident",
          "residents", "residential", "residency"}
REMAIN = {"remain", "remains", "remained", "retain", "retains", "retained", "retaining",
          "retention", "remember", "remembers", "remembered", "memorable", "unforgettable"}
HOLD = {"grab", "grabs", "grabbed", "grabbing", "grip", "grips", "gripping", "arrest",
        "arrested", "arrests"}
OTHER = {"주": 0.8, "ở": 0.8, "trụ": 0.8, "giữ": 0.6}


def value(token: str) -> float:
    s = token.strip().lower()
    if "住" in s:
        return ZHU_NOUN if s in DWELL_NOUNS else ZHU_VERB
    for ch, v in STATION.items():
        if ch in s:
            return v
    if s in STAY:
        return 1.2
    if s in RESIDE:
        return 0.55
    if s in REMAIN or s in HOLD:
        return 0.4
    return OTHER.get(s, 0.0)


def step(carry, prefix, upstream):
    """Activation at this position: set by the current token alone."""
    return carry, float(value(prefix.token_strings[-1]))

programs.luna:
"""Predict token-level cues for living somewhere, staying, and housing.

English stay verbs are the clearest ordinary cues. Residence nouns are smaller,
while Chinese 住 and 住宅 are stronger.
"""

READS = ()

_RESIDENTS = {"resident", "residents", "residency"}
_HOMES = {"apartment", "apartments", "housing", "dwelling", "dwellings"}
_OTHER_STAY_WORDS = {
