"""Digit adjacency, plus negative responses to personnel-related spellings.

Consecutive digit tokens use a shared response curve, strongest for endings
2--5 after 4--9; pairs beginning with 1 have their own curve. Number starts
and digits after a point differ. Personnel words, translations and fragments
are negative, especially staff/faculty; a few following phrase words also
respond. Matching is by spelling, without semantic disambiguation.
"""

READS = ()

# Entries follow the ordinary decimal order, 0 through 9.
SINGLE_DIGIT = (0., -.007, -.006, -.005, -.010, 0., -.088, -.075, .002, .056)
AFTER_SPACE = (0., .006, -.010, -.020, -.005, .010, -.060, -.041, .042, .126)
PAIR_BASE = (-.010, -.137, .039, .213, .183, .163, -.086, -.122, -.150, -.205)
PRECEDING_BOOST = (0., 0., -.017, .079, .696, .511, .949, .664, 1., .695)
ENDING_RESPONSE = (.042, .397, .538, .566, .528, .448, .344, .327, .244, .157)
AFTER_ONE = (.054, -.049, -.042, .032, .014, .030, -.119, -.108, -.039, .079)

PERSONNEL = {
    'staff': -5.24, 'faculty': -3.40, 'employees': -1.26,
    'staffer': -2.0, 'staffers': -2.3, 'staffing': -1.65,
    'faculties': -1.34, 'crews': -.65, 'casts': -.65,
    'employee': -.89, 'personnel': -.94, 'crew': -1.08,
    'admin': -1.33, 'admins': -1.22, 'administration': -.56,
    'administrators': -.65, 'affiliation': -.71, 'family': -.12,
    'administrative': -.27, 'management': -.23, 'leadership': -.35,
    'cast': -.81, 'guests': -.96, 'guest': -.62, 'clergy': -1.71,
    'affiliated': -.77, 'affiliates': -.71, 'colleagues': -.45,
    'officers': -.30, 'police': -.21, 'teachers': -.28,
}
OTHER_PERSONNEL_SPELLINGS = {
    'スタッフ': -3.04, '工作人员': -2.04, '员工': -1.70,
    '員工': -1.40, '职工': -1.65, '干部': -.74,
    '全员': -1.20, '管理员': -1.0, 'Mitarbeiter': -1.0,
    '教师': -.64, '师生': -2.22, '人员': -.43, '員': -.36,
    'сотруд': -1.38, 'сотрудник': -1.46,
}


OF_AFTER = {
    'staff': -1.35, 'faculty': -1.33, 'cast': -.57,
    'crew': -.27, 'employee': -.28, 'employees': -.33,
    'administration': -.20, 'management': -.11, 'personnel': -.15,
}
MEMBERS_AFTER = {'staff': -.84, 'faculty': -.43, 'crew': -.22, 'cast': -.22}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = 0.0
    if len(token) == 1 and token in '0123456789':
        digit = int(token)
        value = SINGLE_DIGIT[digit]
        if previous.endswith(' '):
            value = AFTER_SPACE[digit]
        elif previous.endswith('.'):
            # A first decimal-place digit has a different response from a number's start.
            if digit >= 6:
                value = -.20
            elif digit in (0, 3):
                value = .03
            elif digit == 1:
                value = -.05
            else:
                value = 0.0
        if len(previous) == 1 and previous in '0123456789':
            before = int(previous)
            if before == 1:
                value = AFTER_ONE[digit]
            else:
                value = (PAIR_BASE[digit]
                         + PRECEDING_BOOST[before] * ENDING_RESPONSE[digit])
    else:
        word = token.strip()
        plain = word.lstrip('/_-')
        value = OTHER_PERSONNEL_SPELLINGS.get(word, 0.0)
        if plain.lower() in PERSONNEL:
            value = PERSONNEL[plain.lower()]
            if not token.startswith(' '):
                value *= .85
            if word[0].isupper():
                value *= .91
        elif plain.lower() == 'aff':
            value = -.95 if not token.startswith(' ') else -.48
            if word[0].isupper():
                value = -.86
            if word == 'AFF':
                value = -2.66
            elif previous.endswith('st'):
                value = -2.80
        elif word == 'ulty':
            value = -1.18
        elif word.lower() in ('mployee', 'loyee'):
            value = -.60
    if token.strip().lower() == 'of':
        value = OF_AFTER.get(previous.strip().lower(), 0.0)
    elif token.strip().lower() == 'members':
        value = MEMBERS_AFTER.get(previous.strip().lower(), 0.0)
    return (doc, token), float(value)

programs.haiku:
"""Layer-0 MLP feature for down_proj unit 1797 (a 'staff words / digit-run' feature).

What it does, in plain terms:
1. Staff and personnel words push it strongly negative. "staff" and "faculty" (and their
   capitalised and Japanese or Chinese forms) are the strongest; "employee(s)", "personnel",
   "admin", "crew", "guests" and similar words are weaker.
2. Digits that continue a number (not its first digit) push it positive. The digits 3, 4
   and 5 push most, 2 less, and 0, 1, 6, 7, 8, 9 not at all. The push is much larger when
   the digit just before is 4 or more (as in 198[3], 46[5]) than when it is 0-3.
Everything else is about 0.
"""
READS = ()

STAFF = {
    "staff": -5.0, "faculty": -4.0, "スタッフ": -3.0, "工作人员": -2.0,
    "employees": -1.3, "employee": -1.0, "personnel": -0.9, "admin": -1.3,
    "administration": -0.6, "administrative": -0.3, "cast": -0.7, "crew": -1.0,
    "clergy": -1.8, "guests": -1.0, "guest": -0.6, "officials": -0.2,
}
DIGITS = "0123456789"
# digit push when the previous digit is 4-9 (HIGH) or 0-3 (LOW)
HIGH = {"2": 0.4, "3": 0.6, "4": 0.6, "5": 0.5}
LOW = {"3": 0.15, "4": 0.15, "5": 0.1}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in STAFF:
        return carry, STAFF[word]
    digit = prefix.token_strings[-1]
    if prefix.position > 0 and len(prefix.token_strings[-2]) == 1 and prefix.token_strings[-2] in DIGITS:
        before = prefix.token_strings[-2]
        if before >= "4":
            return carry, HIGH.get(digit, 0.0)
        return carry, LOW.get(digit, 0.0)
    return carry, 0.0

programs.sol:
"""Recognize colons introducing a new line, paragraph, or code block.

The strongest response is to a colon bundled with paragraph breaks. Python
block headers and short labels weaken it; list-introducing or unfinished
phrases strengthen it. The response is somewhat larger near the start of a document. Escaped
line breaks and closing-parenthesis-plus-colon have smaller responses.
"""
import re

READS = ()

CODE_HEADER = re.compile(
    r'^(?:\d+\s+)?(?:async\s+)?'
    r'(def|class|if|elif|else|for|while|with|try|except|finally)\b'
)
LIST_INTRO = re.compile(
    r'\b(include[sd]?|including|such as|as follows|following|'
    r'are|is|be|have|has|that|this|below)\s*$', re.I
)
LABEL = re.compile(
    r'\b(answer|question|explanation|solution|observation|'
    r'introduction|features|results|output|result|case|default|'
    r'public|private|protected)\s*$', re.I
)

EXPLICIT_LIST = re.compile(
    r'\b(include[sd]?|including|such as|like)\s*$', re.I
)
INCOMPLETE = re.compile(
    r'\b(to|either|as|can|could|will|would|must|should)\s*$', re.I
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        line, position = '', 0
    else:
        _, line, position = carry
    s = prefix.token_strings[-1]
    value = 0.0
    if ':' in s or '：' in s:
        breaks = s.count('\n')
        escaped = s.endswith('\\')
        value = 0.01
        if breaks or escaped:
            if breaks == 1:
                value = 1.09
            elif breaks == 2:
                value = 1.42
            elif breaks >= 3:
                value = 1.15
            else:
                value = 0.55
            if ')' in s:
                value -= 0.05
            elif ']' in s:
                value -= 0.09
            if '()' in s:
                value -= 0.17
            if '"' in s or "'" in s:
                value -= 0.20
            if s.startswith(' '):
                value -= 0.37
            if '\r' in s:
                value -= 0.06
            if s.count(':') > 1:
                value -= 0.48
            if CODE_HEADER.match(line.lstrip()):
                value -= 0.07 if escaped else 0.29
            if LIST_INTRO.search(line):
                value += 0.45 if breaks == 1 else 0.33
            if EXPLICIT_LIST.search(line):
                value += 0.30
            elif INCOMPLETE.search(line) and not CODE_HEADER.match(line.lstrip()):
                value += 0.35
            if LABEL.search(line):
                value -= 0.14
            if len(line.split()) < 3 and len(line.strip()) < 40:
                value -= 0.20
            if line.startswith((' ', '\t')):
                value -= 0.08
            if position < 64:
                value += 0.15
            if position < 16:
                value += 0.11
            # A smiley or a slice-ending colon is not a block introduction.
            suffix = s.replace('：', ':').rsplit(':', 1)[1].strip('\r\n')
            if suffix not in ('', '\\'):
                value = 0.45 if '"' in suffix or "'" in suffix else 0.05
        elif ')' in s:
            value = 0.53
        elif ']' in s:
            value = 0.21
    line = (line + s).replace('\\n', '\n').split('\n')[-1][-500:]
    return (doc, line, position + 1), float(value)

"""Negative responses to deployment vocabulary, not computing in general.

Recognize cloud/orchestration products, configuration formats and resource
names.  Long pieces of product names count too.  Ordinary resource words are
weaker after whitespace than in identifier-like spellings.
Decaying traces of Helm, Docker,
cloud and Kubernetes terminology strengthen related resource words.  Helm
charts, Docker images and cloud region/addressing words have special boosts.
These traces reset at document boundaries.
Other tokens stay near 0.
"""
READS = ()
# Levels and topic boosts are rounded estimates from training examples.

TOOLS = set('''kubernetes kubectl kube helm docker terraform ansible
    jenkins vagrant prometheus grafana redis keycloak nginx graphql kafka'''.split())
CLOUD = set('aws azure amazon amazonaws cloud'.split())
RESOURCES = set('''resource resources secret secrets pod pods cluster clusters
    deployment deployments manifest manifests ingress replica replicas'''.split())
COMMON_RESOURCES = set('''service services storage bucket buckets volume volumes
    container containers instance instances provider registry endpoint
    gateway balancer account role policy credentials certificate'''.split())
OPERATIONS = set('''cli ctl ssh dns grpc api apis spec schema metadata metrics
    version versions port log logs controller scheduler agent stack'''.split())
FIELDS = set('name tag tags image images limit limits template rule status'.split())
CHINESE = set('运维 备份 私服 主机 容器 配置 部署 证书'.split())
KEYWORDS = RESOURCES | COMMON_RESOURCES | OPERATIONS | FIELDS | CHINESE

# Characteristic spelling pieces of familiar infrastructure names.
PIECES = {
    'ocker': 'docker', 'enkins': 'jenkins', 'agrant': 'vagrant',
    'afka': 'kafka', 'cloak': 'keycloak',
    'ploy': 'deployment', 'licas': 'replicas', 'crets': 'secrets',
    'napshot': 'storage', 'lemetry': 'metrics', 'etrics': 'metrics',
    'cheduler': 'scheduler', 'ancer': 'balancer',
}


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    if carry is None or carry[0] != doc:
        helm = docker = cloud = kube = 0.0
        tail = ''
    else:
        _, helm, docker, cloud, kube, tail = carry
    token = prefix.token_strings[-1]
    word = token.strip().strip("._-/()[]{}:=,;\"'\\")
    low = word.lower()
    prose = token[:1].isspace()
    capital = word[:1].isupper() and not prose
    if token.strip().lower() == '.yaml':
        value = -2.63
    elif token.strip().lower() == '.yml':
        value = -1.62
    elif low == 'ubernetes':
        value = -3.97
    elif low == 'etheus':
        value = -3.74
    # Names from the Kubernetes Go API and metadata packages.
    elif low == 'apimachinery':
        value = -5.3
    elif low in {'corev', 'metav', 'objectmeta'}:
        value = -2.8
    elif low == 'ambda':
        value = -1.7
    # Cloud SDK / infrastructure provisioning tools.
    elif low in {'boto', 'pulumi'}:
        value = -3.2
    else:
        low = PIECES.get(low, low)
        if low in TOOLS:
            value = -1.65
        elif low in CLOUD:
            value = -0.9 if prose else -1.4
        elif low == 'config':
            value = -1.0
        elif low == 'configuration':
            value = -0.36 if prose else -0.65
        elif low == 'conf':
            value = -0.09 if prose else -0.3
        elif low in {'yaml', 'yml'}:
            value = -1.3
        elif low in RESOURCES:
            value = -0.42 if prose else (-1.4 if capital else -1.1)
        elif low in COMMON_RESOURCES:
            value = -0.16 if prose else -0.8
        elif low == 'log':
            value = -0.5 if token.startswith('/') else -0.05
        elif low == 'metrics':
            value = -0.65 if prose else -1.3
        elif low in OPERATIONS:
            value = -0.25 if prose else -0.55
        elif low in FIELDS:
            value = -0.02 if prose else (-0.25 if capital else -0.13)
        elif low in CHINESE:
            value = -1.1 if low in {'运维', '备份', '私服'} else -0.6
        elif low in {'nil', 'omitempty', 'sprintf', 'eof'}:
            value = -0.3 if prose else -0.7
        elif word in {'Arn', 'IAM'} and token.startswith(' '):
            value = -1.1
        else:
            value = -0.002

    # A few infrastructure meanings depend on the local topic, not just spelling.
    value *= 0.96
    technical = max(helm, docker, cloud, kube)
    keyword = low in KEYWORDS
    if keyword:
        value -= 1.08 * technical
    if low in {'chart', 'charts'}:
        value = -0.1 - 2.7 * helm
    if low in {'image', 'images', 'dangling'}:
        value -= 1.95 * docker
    if low in {'region', 'regions', 'client', 'arn', 'iam'}:
        value -= 1.62 * cloud
    if token in {'-east', '-west'}:
        value -= 2.57 * cloud
    if low == 'ube' and tail.lower().endswith('k'):
        value = -2.0

    # Topic memories decay over roughly thirty tokens and never cross documents.
    helm = 1.0 if low == 'helm' else helm * 0.97
    docker = 1.0 if low in {'docker', 'ocker'} else docker * 0.97
    cloud = 1.0 if low in {'aws', 'azure', 'boto', 'amazonaws'} else cloud * 0.97
    kube = 1.0 if low in {'kubernetes', 'ubernetes', 'kubectl', 'kube'} else kube * 0.97
    tail = (tail + token)[-16:] if token[-1:].isalpha() else ''
    return (doc, helm, docker, cloud, kube, tail), value

"""A multilingual coordination detector, not a clause parser.

Space-prefixed lowercase conjunctions are strongest between words and much
weaker after punctuation or numbers. Commas in short lists partially restore
'and'; contrastive 'but' does not need this context gate. Word length, case,
and common grammatical endings refine English coordination strength. Language
cues distinguish Spanish 'y' and Italian/Portuguese 'e' from variable names.
Comparison words and written joining signs receive smaller responses.
"""
import re

READS = ()

# Additive/alternative conjunctions, calibrated by language.
JOINERS = {
    'and': 1.45, 'or': 1.35, 'und': 1.85, 'oder': 1.45,
    'et': 1.50, 'ou': 1.20, 'и': 1.60, 'или': 1.55,
    'og': 1.15, 'och': 1.15, 'eller': 1.30, 'dan': 1.30,
    've': 1.20, 'veya': 1.30, 'và': 2.50, 'hoặc': 1.70,
    'és': 0.95, 'și': 0.90, 'şi': 0.85, 'ja': 0.75,
    'oraz': 0.85, 'bzw': 1.65, 'atau': 1.25,
    'و': 1.40, 'أو': 1.35, 'وال': 0.95, 'وم': 1.10,
    'والم': 1.10, 'والأ': 0.75, 'وإ': 1.05,
    '및': 2.40, '또는': 1.80,
}
UNSPACED_JOINERS = {
    '和': 1.80, '与': 1.35, '與': 1.30, '及': 1.50,
    '或': 1.95, '或者': 1.40, '以及': 0.90,
    'と': 1.20, 'や': 1.20, '와': 2.05, '과': 1.50, 'และ': 2.15,
}
CONTRAST = {
    'but': 1.26, 'But': 1.00, 'BUT': 0.76,
    'но': 0.74, 'Но': 0.53, 'mais': 0.61, 'pero': 0.83,
    'aber': 0.34, 'sondern': 0.50, 'mas': 0.31,
    'nhưng': 0.75, 'ma': 0.28,
}
OTHER_LINKS = {
    '但': 0.67, '但是': 0.47, 'けど': 0.51, '지만': 0.49,
    '又': 0.93, '并': 0.60, '且': -0.48, '而且': -0.48,
    '・': 0.58, '＆': 0.80,
}
FUNCTION_WORDS = frozenset('''a an the of to in on at for from by with as
    is are was were be been being do does did have has had can could will
    would shall should may might must it this that these those there here
    me us them one two three four five six seven eight nine ten more less
    than whether and or not'''.split())
LANGUAGE_CUES = {
    'y': frozenset('''de la el los las para que con una un del por
        su sus es como en'''.split()),
    'e': frozenset('''de da do que com para não uma os il lo gli per
        di con che del della sono'''.split()),
}
ENGLISH_CUES = frozenset('''the of this that was were are has have
    from with not let return'''.split())


def word_strength(word):
    """A compact approximation using familiar word shapes and function words."""
    lower = word.lower()
    strength = 1.08 + 0.055 * min(len(word), 10)
    if len(word) == 1:
        strength = 0.80
    elif word.istitle():
        strength += 0.23
    if lower in FUNCTION_WORDS:
        strength -= 0.40
    if lower.endswith(('ed', 'ly')):
        strength -= 0.30
    if lower.endswith('s'):
        strength += 0.09
    return strength


def context_scale(previous, prior_word):
    last = previous[-1:]
    if not last:
        return 0.10
    if last in ',;:，；：、':
        return -0.03
    if last in '.!?。！？\n\r–—':
        return 0.15
    if last.isspace():
        return 0.23
    if last.isdigit():
        return 0.43
    if last in ')]}）】$%':
        return 0.48
    if last in '\'"’”`»':
        return 0.62
    if last.isalpha():
        return 0.55 if prior_word.lower() in FUNCTION_WORDS else 1.0
    return 0.42


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, tail = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip()
    spaced = token.startswith(' ')
    match = re.search(r'[^\W\d_]+$', tail)
    prior_word = match[0] if match else ''
    scale = context_scale(previous, prior_word)
    value = 0.0
    if token in (' and', ' or', ' &'):
        value = {' and': 1.45, ' or': 1.35, ' &': 1.35}[token] * scale
        if previous[-1:].isalpha() and word != '&':
            value = word_strength(prior_word) - (0.04 if word == 'or' else 0.0)
        elif previous.endswith(',') and word != '&':
            sentence = re.split(r'[.!?;\n]', tail)[-1][-40:]
            commas = min(2, max(0, sentence.count(',') - 1))
            value = (-0.22 + 0.17 * commas) if word == 'or' else (-0.18 + 0.27 * commas)
    elif spaced and word in JOINERS:
        value = JOINERS[word] * scale
    elif spaced and word in LANGUAGE_CUES:
        words = set(re.findall(r'\w+', tail.lower()))
        strength = min(1.20, 0.15 + 0.40 * len(words & LANGUAGE_CUES[word]))
        if words & ENGLISH_CUES:
            strength *= 0.20
        value = strength * scale
    elif word in UNSPACED_JOINERS:
        value = UNSPACED_JOINERS[word] * scale
    elif spaced and word in CONTRAST:
        value = CONTRAST[word]
    elif word in ('but', 'But', 'BUT'):
        value = CONTRAST[word] - 0.24
    elif word in OTHER_LINKS:
        value = OTHER_LINKS[word]
    elif word in ('-and', '_and', '—and', '-but', '—but'):
        value = 1.15 if 'and' in word else 1.08
    elif word in ('And', 'Und', 'Et', 'И'):
        value = 0.16
    elif token == ' AND':
        value = 0.75 * scale
    elif token == ' OR':
        value = 0.26
    elif word == '&':
        value = 0.18
    elif word == '+':
        value = 0.39 if spaced else 0.24
    elif word == '/':
        value = 0.33 if spaced else (0.62 if previous[-1:].isalpha() else 0.07)
        if token.endswith('\n'):
            value = 0.21
    elif word == '://':
        value = 0.57
    elif word == 'than':
        value = 0.68 if spaced else 0.31
        if prior_word.lower() in ('rather', 'other'):
            value = 0.08
        elif prior_word.lower() == 'more' or prior_word.lower().endswith('er'):
            value = 0.83
    elif word in ('vs', 'versus'):
        value = 0.95 if spaced else 0.30
    elif word in ('等', 'など', 'などの', 'などで', 'などが', '등', '등의'):
        value = 0.90
    return (doc, token, (tail + token)[-160:]), float(value)

programs.haiku:
"""Component layers.0.mlp.down_proj:1802 -- a "joining word" detector.

It fires on words that join two parallel items: "and", "or", "but" and their
equivalents in other languages (und, oder, и, или, et, y, e, ou, و, 和, 与, 或, &).
Its strength depends on what comes right before the joining word:

- after a content word (a noun, adjective or verb, e.g. "Library and Museum",
  "science and"): strong, about 1.45;
- after a number, a closing bracket or quote, or a function word ("of", "the"):
  weaker, about 0.7;
- after a comma or semicolon, ", and" starting a new clause or list item: about 0.
  "but" is the exception and fires after a comma too.

Smaller extras: comparative "than" (0.7), "+" (0.4), and a slash between words
(0.8; after a digit, 0.1). Everything else is 0.

Main program: the `step` function below. It needs no carry, since it reads only
the newest token and the one before it.
"""

