import re

READS: tuple[str, ...] = ()

# (ordinary activation, extra activation near command-line markers).
FAMILIES = (
    ((-1.46, -0.94), 'cd'),
    ((-1.72, -0.63), 'bash zsh csh ksh powershell'),
    ((-2.30, -0.14), 'chmod chown chgrp sudo'),
    ((-1.36, -0.14), 'grep'),
    ((-0.90, -0.79), 'cat'),
    ((-0.69, -0.73), 'sed awk'),
    ((-0.27, -1.02), 'ls mkdir rmdir touch cp mv rm xargs nohup'),
    ((-1.14, 0.00), 'ssh scp rsync'),
    ((-0.39, -0.23), 'curl wget ping'),
    ((-0.17, -0.29), 'apt yum brew'),
    ((-0.09, -0.19), 'make cmake npm pip'),
    ((-0.55, 0.02), 'git checkout'),
    ((-1.14, -0.47), 'command cmd'),
    ((-1.53, -0.35), 'commands cmds'),
    ((-1.69, -0.22), 'scripts'),
    ((-0.24, -0.14), 'terminal terminals console'),
    ((-0.67, -0.59), 'shell shells'),
    ((-0.36, -0.48), 'args argv argument arguments'),
    ((-0.46, -0.20), 'tool tools utility utilities'),
    ((-0.01, -0.18), 'variable variables'),
    ((-0.11, 0.01), 'permission permissions'),
    ((-0.34, -0.25), 'exit'),
    ((-0.33, -0.17), 'root hosts'),
    ((-0.18, -0.45), 'env export unset source alias'),
    ((-0.20, -0.48), 'dir directory directories'),
    ((-0.8, 0.), 'cli'),
    ((-0.5, 0.), 'usr'),
)
WORDS = {word: rule for rule, words in FAMILIES for word in words.split()}

SHELL = re.compile(
    r'#!/|/bin/|/dev/null|&&|\b(?:bash|zsh|shell|sudo|chmod|grep)\b'
)
SCRIPT = re.compile(
    r'#!/|(?:\];?\s*then|;\s*then|\bfi|\besac)[ \t]*(?:\n|\\n)|'
    r'\b(?:bash|zsh|sh|shell)[ \t]*(?:\n|\\n)|'
    r'\b(?:export|unset|alias)\s+[A-Z_]|'
    r'\$\((?:pwd|dirname|basename|cat|grep|echo|sed|date|which)\b|'
    r'\[\[? -[a-zA-Z]|"\$(?:\{|[A-Z_])|'
    r'(?:\n|\\n)\s*(?:echo|cd|exit|export)\b'
)
PHP = re.compile(
    r'<\?php|->|\b(?:function|public|private|protected)\b|'
    r'\$this|\);|else\s*\{|if\s*\('
)


def follows(text, words):
    """Does the preceding text end with one of these whole words?"""
    pattern = r'\b(?:' + '|'.join(words.split()) + r')\s*$'
    return bool(re.search(pattern, text))


