    elif word == 'alias':
        value = -0.9
    elif word == 'source':
        value = -0.03
    elif word == 'export':
        value = -0.65 - 0.8 * shell
    elif word == 'install':
        value = -1.5 if follows(prior, 'apt apt-get pip npm yum brew') else -0.2
    elif word == 'cd' and prior.endswith('\\'):
        value = 0.0
    elif word == 'echo':
        value = -4.0 if script else -1.3 if php else -2.8
        if t != t.lower():
            value = -0.6
    elif word == 'command' and follows(prior, 'military army naval combat central supreme'):
        value = -0.15
    elif word == 'command' and follows(prior, 'bash shell'):
        value = -3.6
    elif s == ' Command':
        value = -0.55
    elif word == 'script' and follows(
        prior, 'film movie screenplay pilot television drama'
