    if t == '.sh':
        code = bool(re.search(r'\b(?:if|return|def)\b', prior))
        value = -1.1 if (php or code) and not shell else -4.0
    elif t in {'/sh', '/bash'}:
        value = -6.2 if '#!' in prior[-20:] else -3.0
    elif t in {'.bashrc', '.zshrc'}:
        value = -4.0
    elif t in {'sh', '_sh', 'ash'}:
        value = -0.5
    elif t in {'/bin', '/sbin'}:
        value = -2.25
    elif t == '/local':
        value = -1.0
    elif t in {'/env', '/perl'}:
        value = -1.6
    elif t == '/null':
        value = -2.75
    elif t in {'.yml', '.yaml', '.conf', '.ci', '.docker', '.git', '.json', '.txt'}:
        value = {
            '.yml': -1.25, '.yaml': -0.7, '.conf': -1.5, '.ci': -1.5,
            '.docker': -1.6, '.git': -0.7, '.json': -0.4, '.txt': -0.35,
        }[t]
    elif word == 'file' and joined.lower().endswith(('makefile', 'dockerfile')):
        value = -2.8
    elif joined.lower().endswith('docker'):
        value = -1.2
    elif t in {'RUN', '_RUN'}:
        value = -1.1
    elif t == 'EOF':
        value = -1.8
    elif t == 'fi' and not fragment:
        value = -4.5 if script else -0.4
    elif t in {'do', 'done', 'then', 'else', 'esac'} and script and not fragment:
        value = -1.8
    elif t in {'export', 'unset', 'alias'} and script:
        value = -2.8
    elif t == '.list' and (prior.endswith('/sources') or '/apt/' in prior):
        value = -4.8
    elif t == '/sources' and '/apt' in prior:
        value = -3.2
    elif t == '-get' and prior.endswith('apt'):
        value = -2.6
    elif t in {'Sh', 'SH'}:
        value = -0.15
    elif t == '-cli':
        value = -1.4
    elif t == '&&':
        value = -0.9 - 0.5 * shell + 0.5 * php if s.startswith(' ') else -0.3
    elif t == '>&':
        value = -1.1
    elif t == './':
        value = -1.0
    elif t == '||':
        value = -0.2
    elif t in {'<<', '<<<'}:
        value = -2.2 if script else -0.35
    elif t == '#!/':
        value = -1.65
    elif t in {'"$', '"${', '="$','="${'}:
        value = -3.3 if script else -2.3
    elif t in {'=$(', '=$((', '="$('}:
        value = -4.0
    elif t in {'=$', '/$'}:
        value = -1.6
    elif t in {'${', '/${', '$('}:
        value = -3.0 if script else -0.55
    elif t == '$':
        value = -2.6 if script else 0.04
    elif t in {'"', "'"}:
        value = -0.65 if script else 0.
    elif t == '#':
        value = -1.0 if script else -0.10
    elif script and (t in {'];', ']];'} or t.startswith(';;')):
        value = -1.8
    return (doc, joined[-160:]), float(value)

