"""layers.0.mlp.down_proj:1805 -- a "joined symbol" detector.

The component reads the current token only. It responds to short runs of punctuation
and operator characters that join things in code and maths: "/\n", "-\n", "_;\n",
"-,", " +=", "/(", "_{", "/.", "__/". It is silent on words, digits, spaces, and on
repeated runs such as "--", "//", "**", "__". A run qualifies when it contains a joiner
(_ - / + *) and at least one other, different symbol. Among the qualifying runs:

- the more of ",", ";", "=", "$", "%", "~", "\\", "_", "^" it contains, the more it fires;
- a line break in it adds a lot; a leading space and longer runs subtract;
- quotes, angle brackets, colons, dots and similar marks subtract; opening brackets add a little.

A lone " /" (space then slash) fires moderately. Everything else predicts 0.
"""

READS = ()

JOINERS = set("_-/+*")
STRONG = set(",;=$%~\\_^")
OPENERS = set("({[")
WEAK = set("<>\"`*-:.!'+)}]#")


def _is_symbol_run(text):
    """True if every character is punctuation/symbol, or a line break."""
    return all(ch in "\n\r" or (not ch.isalnum() and not ch.isspace()) for ch in text)


def _activation(token):
    if token == " /":
        return 0.5
    core = token.strip(" \t")
    if len(core) < 2 or not _is_symbol_run(core):
        return 0.0
    if not any(ch in JOINERS for ch in core) or len(set(core)) < 2:
        return 0.0
    value = 0.6
    if "\n" in token:
        value += 0.9
    if token.startswith(" "):
        value -= 0.19
    value -= 0.3 * (len(core) - 2)
    for ch in core:
        if ch in STRONG:
            value += 0.55
        elif ch in OPENERS:
            value += 0.05
        elif ch in WEAK:
            value -= 0.22
    return max(value, 0.0)


def step(carry, prefix, upstream):
    return None, float(_activation(prefix.token_strings[-1]))

