"""A spelling-based approximation to a suffix-like activation.

Alphabetic pieces attached to a preceding letter get a signal based on script,
length, vowels and familiar inflectional endings. Word starts, punctuation and
all-uppercase pieces are nearly silent. Neighboring vowels, the preceding
piece's length and capitalization adjust the estimate. Decaying function-word
and accent clues raise it in European-language prose relative to English.
Dialogue tags and Unicode byte fragments have separate estimates. This uses
no future tokens and does not claim to identify actual word endings.
"""
import unicodedata

READS = ()
VOWELS = set('aeiouy')
CASE_ENDINGS = set('al an ar ad at er et in is it on or un us'.split())
ROMANCE_ENDINGS = set('ado ada ados adas ato ata ano ana ido ida ito ita '
                      'ico ica oso osa are ere ire ino ina uro ura'.split())
GERMANIC_ENDINGS = set('ern den ens ien ten'.split())
SLAVIC_ENDINGS = set('ом ам ем им ум ах их ых ой ий ей ая яя ое ее ие ые '
                     'ую юю ия ии ка ки ку та то ту ат ут ами ями ого ему'.split())
ENGLISH_INFLECTIONS = set('ed ing ers est ous ity'.split())
NOUN_DERIVATIONS = set('ment ness ism ist tion ions ization'.split())
WEAK_ENDINGS = ENGLISH_INFLECTIONS | NOUN_DERIVATIONS | {'ly', 'ish'}
FOREIGN_WORDS = set('de la el que en et le les des du un une con per una del '
                    'di il che non und der die das den dem ein eine von zu '
                    'mit nicht ist im auf voor het een och att som'.split())
ENGLISH_WORDS = set('the and of to with was were is for are this that have '
                    'from not but you it be'.split())
TAGS = {
    '</tool_response>': 0.65,
    '<tool_response>': 0.17,
    '<think>': 0.21,
    '</think>': 0.12,
    '</tool_call>': 0.05,
    '<|im_start|>': -0.02,
    '<|im_end|>': -0.05,
    '<|endoftext|>': -0.02,
}


# Each row is a familiar family of endings and its fitted strength.
LATIN_ENDING_CLASSES = (
    ({'en', 'es', 'as', 'os', 'ur'}, 0.35),  # Plural/case endings.
    (CASE_ENDINGS, 0.25),
    ({'le', 're'}, 0.18),
    (ROMANCE_ENDINGS | GERMANIC_ENDINGS, 0.16),
    (ENGLISH_INFLECTIONS, 0.02),
    (NOUN_DERIVATIONS | {'ly', 'ish'}, -0.08),
    ({'ile', 'ory', 'ure'}, 0.24),  # Vowel-liquid derivational tails.
)


def vowel(c):
    return unicodedata.normalize('NFD', c)[0] in VOWELS


def latin_piece(s):
    n = len(s)
    if n == 1:
        marks = unicodedata.normalize('NFD', s)[1:]
        if marks:
            if any(c in marks for c in '\u0308\u0302\u030c'):
                return 0.04  # Umlaut, circumflex, or caron.
            if any(c in marks for c in '\u0306\u0328\u030b'):
                return 0.29  # Breve, ogonek, or double acute.
            return 0.15
        if s in 'ao':
            return 0.36
        if vowel(s):
            return 0.29
        return 0.22 if s in 'st' else 0.08
    for endings, strength in LATIN_ENDING_CLASSES:
        if s in endings:
            return strength
    if n == 2:
        return 0.12 if any(vowel(c) for c in s) else 0.03
    if n == 3:
        return 0.08 if vowel(s[0]) else 0.01
    return -0.01


def slavic_piece(s):
    if len(s) == 1:
        if s in 'аоу':
            return 0.52
        if s in 'еиыі':
            return 0.37
        if s in 'яёю':
            return 0.20
        if s in 'ьй':
            return 0.20
        return -0.09 if s in 'чшщц' else 0.10
    if s in SLAVIC_ENDINGS:
