    return 0.06 if len(s) == 2 else -0.05


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    language = carry[1] if carry is not None and carry[0] == doc else 0.0
    word = s.strip().lower() if s.startswith(' ') else ''
    clue = 0.3 * ((word in FOREIGN_WORDS) - (word in ENGLISH_WORDS))
    if any(ord(c) > 127 and 'LATIN' in unicodedata.name(c, '') for c in s):
        clue += 0.1
