        if '\ufffd' in prev:
            return carry, 0.10
        return carry, 0.0 if prev[-1:].isalpha() else 0.05
    if not s.isalpha() or s != s.strip() or s.isupper():
        return carry, -0.002
    if not prev[-1:].isalpha():
        return carry, 0.015
    script = unicodedata.name(s[0], '').split()[0]
    stem_length = min(6, len(prev.strip())) - 3
    if script == 'LATIN':
        value = latin_piece(s)
        # Distinguish vowel sequences from consonant-vowel syllable boundaries.
        if vowel(prev[-1]):
            if len(s) == 1:
                if vowel(s):
                    value -= 0.08
                elif s.isascii() and s not in 'st':
                    value += 0.09
            elif len(s) == 2 and vowel(s[0]):
                value -= 0.04
        if (len(s) <= 3 or s in ROMANCE_ENDINGS) and s not in WEAK_ENDINGS:
            value += 0.08 * language
        if len(s) == 1 and s in VOWELS:
            value += 0.03 * stem_length
        elif len(s) == 1 and s.isascii() and s not in 'st':
            value -= 0.015 * stem_length
    elif script == 'CYRILLIC':
        value = slavic_piece(s)
        if len(s) == 1:
            value -= 0.024 * stem_length
            if s in 'аоуеиыіяёю' and prev[-1] in 'аеёиоуыэюяіїє':
                value -= 0.12
    elif script == 'GREEK':
        value = 0.41 if s == 'ς' else 0.09 if len(s) == 1 else -0.05
    elif script == 'ARABIC':
        value = 0.34 if len(s) == 1 else 0.02
    else:
        value = 0.005
    if not prev[-1:].islower():
        value *= 0.5
    return carry, float(value)

programs.haiku:
"""Word-piece detector for layers.0.mlp.down_proj:1806 (layer 0 MLP, one of 2048 rank-one pieces).

What it does: it fires on pieces of a split word that begin with no leading
space, i.e. the 2nd, 3rd... piece of a word the tokenizer broke up. Its
strongest responses are to single vowel letters used as word endings or
fragments, especially Cyrillic а, у, о, ы, е (about 0.4) and Latin vowels
(about 0.2), and to a few short Latin fragments (en, es, os, ar, ...; about
0.3). Single consonants and two-letter pieces are weakly positive (about 0.06).
Whole words (leading space), longer pieces, digits and punctuation are ~0.
Partial UTF-8 bytes (U+FFFD) and chat/tool markers (</tool_response>) respond too.
"""

READS = ()

CYRILLIC_VOWELS = set("аоуыеиюя")
VOWELS = set("aeiouyаеёиоуыэюяäöüøåéèêáíóúàâîôûąęőýςτηωιοαεου")
LATIN_FRAGMENTS = {"en", "es", "os", "as", "ar", "ur", "er", "ato", "ute"}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if "�" in s:
        return None, 0.07
    if s.startswith("</"):
        return None, 0.25
    if s == "" or s.startswith(" ") or not s.isalpha():
        return None, 0.0
    if len(s) == 1:
        if s in CYRILLIC_VOWELS:
            return None, 0.4
        if s in VOWELS:
            return None, 0.2
        if s.isupper():
            return None, 0.0
        return None, 0.06
    if s in LATIN_FRAGMENTS:
        return None, 0.3
    if len(s) == 2:
        return None, 0.06
    if len(s) <= 4:
        return None, 0.02
    return None, -0.01

