programs.sol:
"""Approximate a possessive-ending detector, with two separator responses.

English noun + apostrophe-s is strongly positive, but common contractions
(it's, that's, let's, etc.) are not. A bare apostrophe after a plural -s
also responds. Numeric hyphens and single tab characters are secondary
triggers; a tab immediately following another tab has little response.
Spelling variants, apostrophe-n abbreviations, and quote boundaries get
small corrections. Other tokens are predicted as zero; their numerous
weak, word-specific responses are not modeled. Context is the last 80
characters, reset at document boundaries.
"""
import re

READS = ()
CONTRACTION_BASES = {'it', 'that', 'there', 'he', 'she', 'let'}
QUESTION_BASES = {'what', 'who', 'how', 'where', 'when', 'why'}
NONPLURAL_S = {'is', 'was', 'as', 'has', 'his', 'this', 'thus', 'yes', 'us'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    # Case changes also separate joined words, as in escaped-text snippets.
    match = re.search(r'(?:[A-Z]?[a-z]+|[A-Z]+)\Z', tail)
    word = match[0].lower() if match else ''
    value = 0.0
    if token in ("'s", '’s', '‘s', '´s', "'S", '’S'):
        if word in CONTRACTION_BASES:
            value = -0.105
        elif word == 'here':
            value = 0.03
        elif word in QUESTION_BASES:
            value = 0.16
        else:
            value = (0.92 if token.endswith('S') else 1.1) if word else 0.8
    elif token == 's' and tail.endswith(("'", '’', '\x92')):
        value = 0.14 if tail[-2:-1].isspace() else 0.63
    elif token in ("'n", '’n'):
        value = 0.35
    elif token in ("'", '’', "\\'"):
        if len(word) > 2 and word.endswith('s'):
            before_word = tail[:-len(word)]
            if before_word.endswith(("'", '‘')):
                value = 0.10
            else:
                value = 0.64 if word not in NONPLURAL_S else 0.12
        elif len(word) == 1:
            value = -0.04
    elif token in ('-', ' -', '–', '−', '—'):
        if tail[-1:].isdigit():
            if token == '-':
                value = 0.55
            elif token == ' -':
                value = 0.11
            else:
                value = 0.25
        elif token == '-' and tail[-1:].isalpha():
            value = 0.05
        elif token == '–':
            value = -0.16
    elif token == '\t':
        if tail.endswith('\t'):
            value = 0.05
        elif tail.endswith('\n') or not tail:
            value = 0.485
        else:
            value = 0.385
    elif token == '\t\t':
        value = 0.10 if tail.endswith('\n') else -0.025
    return (doc, (tail + token)[-80:]), value

programs.haiku:
"""Possessive-'s detector (layer 0, MLP down_proj, component 1807).

Main job: fire on the possessive clitic 's or ’s written after a noun, as in
"the manufacturer's instructions", "Children's Hospital", "Parkinson's disease",
"the veteran's claim". Typical value about 1.1 (range roughly 0.7 to 1.6).

The same token after a pronoun or after let/that/there is a contraction
("it's", "that's", "he's", "let's"), not a possessive. There the component is
slightly negative, about -0.1.

Two weaker cases:
- a plural possessive apostrophe after a word ending in s ("workers'",
  "soldiers’"): about 0.5;
- a hyphen right after a digit, as in a number range ("20-29", "10-28"): about 0.55;
- a tab that starts an indented line (after a newline or a space), as in code
  or tables: about 0.45. A tab right after another tab stays near 0.

Everything else is about 0.
"""

READS = ()

# Pronouns and function words that take a contraction 's (it's, that's, let's).
CONTRACTION_HOSTS = {
    "it", "that", "he", "she", "there", "let", "here", "what", "who", "where", "this", "how",
}
POSSESSIVE_MARKS = {"'s", "’s", "'S"}


def _word(text):
    return text.strip().strip("'’").lower()


def step(carry, prefix, upstream):
    t = prefix.position
    tok = prefix.token_strings[t]
    if t == 0 or prefix.document_ids[t - 1] != prefix.document_ids[t]:
        return None, 0.0
    prev = prefix.token_strings[t - 1]

    if tok in POSSESSIVE_MARKS:
        if _word(prev) in CONTRACTION_HOSTS:
            return None, -0.1
        return None, 1.1

    if tok in ("'", "’") and prev[-1:] == "s":
        return None, 0.5

    if tok == "-" and prev[-1:].isdigit():
        return None, 0.55

    if tok == "\t" and prev != "\t":
        return None, 0.45 if prev.endswith(("\n", " ")) else 0.0

    return None, 0.0

programs.luna:
"""Recognize apostrophe-s tokens and a couple of formatted separators.

The response is usually strongest on apostrophe-s endings. Numeric dashes
and tabs get smaller estimates; other tokens get zero.
"""
READS = ()

APOSTROPHES = "'’‘`"
DASHES = "-–—−"


def is_numeric_piece(text):
    text = text.strip()
    if not text:
        return False
    if text.isdigit():
        return True
    return all(c in "0123456789abcdefABCDEF" for c in text) and any(
        c.isdigit() for c in text
    )


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]

    if len(token) >= 2 and token[-1].lower() == "s" and token[-2] in APOSTROPHES:
        return None, 0.65

    if "\t" in token:
        return None, 0.08

    if token.strip() in DASHES and len(prefix.token_ids) >= 2:
        same_document = prefix.document_ids[-1] == prefix.document_ids[-2]
        previous = prefix.token_strings[-2] if same_document else ""
        if is_numeric_piece(previous):
            return None, 0.30

    return None, 0.0

"""Approximate activations with sparse cues about success and function.

The largest response is for standalone “功”; smaller cues mark “successfully,”
functional/correct operation, and related Chinese and Japanese terms.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().casefold()

    if "successfully" in word:
        value = -2.2
    elif "functionality" in word:
        value = -1.0
    elif "functional" in word:
        value = -1.4
    elif "correctly" in word:
        value = -0.6
    elif "successful" in word:
        value = -1.0
    elif any(part in word for part in ("success", "succeed", "uccess")):
        value = -0.7
    elif "成功" in word:
        value = -0.75 if word.endswith("的") else -1.5
    elif "功能" in word:
        value = -2.3
    elif word == "功":
        value = -5.0
    elif "効" in word or "效果" in word:
        value = -0.6
    else:
        value = 0.0

    # In some Japanese words the useful character is split across byte tokens.
    if value == 0.0 and "\ufffd" in token:
        if prefix.text_prefixes[-1].endswith("効"):
            value = -0.6

    return carry, float(value)

programs.sol:
"""A lexical organization/tissue detector, not general semantic inference.

Organization words and tissue words get strong negative values; Chinese 组织
covers both senses. Org/organ and issue fragments get weaker values, as do a few
textile words and several isolated verb-ending fragments.
Remember the unfinished English word for Organ + ized or
T + issue, and for the connecting words in 'organization of'/'organized the'.
Reset that memory at document boundaries. Unrecognized text gets zero.
"""
import re

READS = ()

ORGANIZATION_NOUNS = {
    'organization', 'organizations', 'organisation', 'organisations',
}
ORGANIZING_VERBS = {
    'organize', 'organized', 'organizing', 'organise', 'organised', 'organising',
}
ORGANIZERS = {'organizer', 'organizers', 'organiser', 'organisers'}
ORGANIZATION_SUFFIXES = {
    'ize', 'ized', 'izing', 'izes', 'ise', 'ised', 'ising', 'ises',
    'ization', 'izations', 'isation', 'isations', 'izational', 'ational',
    'izer', 'izers', 'iser', 'isers',
}
TEXTILE_WORDS = {
    'fabric', 'fabrics', 'textile', 'textiles', 'stitch', 'stitches',
    'stitching', 'knit', 'knitting', 'woven',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    text = token.strip()
    lower, prev = text.lower(), previous.lower()
    spaced = token[:1].isspace()
    match = re.search(r'[A-Za-z]+\Z', previous + token)
    word = match.group()[-40:] if match else ''
    value = 0.0

    if text in ('组织', '組織', '조직'):
        value = {'组织': -6.0, '組織': -4.75, '조직': -3.2}[text]
    elif '组织' in text:
        value = -2.5
    elif lower.startswith('организ'):
        value = -1.5
    elif lower == 'organización':
        value = -2.9
    elif lower == 'organizational':
        value = -4.1
    elif lower in ORGANIZATION_NOUNS:
        value = -3.75
        if text == 'Organization' and spaced:
            value = -4.3
    elif lower in ORGANIZING_VERBS:
        value = -2.7 if lower == 'organize' else -2.4
    elif lower in ORGANIZERS:
        value = -1.3
    elif lower in ('organiz', 'organis'):
        value = -3.3
    elif not spaced and prev.endswith(('organ', 'organis', 'organiz')) \
            and lower in ORGANIZATION_SUFFIXES:
        value = -3.8 if lower == 'izational' else -2.4
        if lower in ('izer', 'izers', 'iser', 'isers'):
            value = -1.3
    elif lower in ('tissue', 'tissues') or (not spaced and prev in ('t', 'nt')
                                           and lower in ('issue', 'issues')):
        value = -3.45 if lower in ('tissue', 'issue') else -3.0
        if prev in ('soft', 'connective'):
            value -= 0.7
    elif lower in ('organ', 'organs'):
        value = -1.5 if lower == 'organ' else -0.84
    elif lower.strip('./-_(') == 'org':
        value = -2.2 if spaced or text.startswith('/') else -1.0
    elif lower.strip('/_-(') in ('issue', 'issues'):
        value = -1.1 if spaced or text[:1] in '/_-(' else -2.2
        if text[:1].isupper():
            value = -1.3
    elif lower in ('issued', 'issuing'):
        value = -0.4
    elif text == '织':
        value = -4.0
    elif text in ('问题', '的问题', '問題'):
        value = -0.45
    elif lower == 'yarn':
        value = -0.75
    elif lower in TEXTILE_WORDS:
        value = -0.4
    elif not spaced and lower in ('ize', 'ized', 'ised', 'isation'):
        value = -0.17

    if lower == 'of' and prev in ORGANIZATION_NOUNS:
        value = -1.1
    elif lower == 'of' and prev in ('tissue', 'tissues', 'organ', 'organs'):
        value = -0.8
    elif lower in ('the', 'by') and prev in ORGANIZING_VERBS:
        value = -0.65 if lower == 'the' else -0.23
    return (doc, word), value

