"""Approximate a lexical readiness/preparedness signal.

'Ready' and standalone 備/备 are the strongest negative triggers. Availability,
preparation, equipment, and prior completion are weaker triggers. This is a
word-form detector, not a general judgement of whether someone is ready: spelling,
capitalization, and token boundaries matter. Korean 비 is an associated syllable
that also fires outside the preparation word 준비. Short collocations continue
onto 'to', 'for', and 'of'. Other tokens receive zero; document changes reset state.
"""

READS = ()

# Small semantic word families, including a few translations.
WORD_GROUPS = (
    (-1.08, 'available readily eager handy equipped'),
    (-0.93, 'already'),
    (-0.80, 'prepared preparations preparing availability reserve backup'),
    (-0.66, 'prepare prepares preparation prep waiting awaiting unavailable'),
    (-0.60, 'reserves ripe tired'),
    (-0.52, 'equipment eligible eagerly busy'),
    (-0.80, 'weary ineligible'),
    (-0.36, 'willing capable equip'),
    (-0.47, 'prepar'),
    (-0.16, 'able'),
    (-0.55, 'déjà уже bereits pronto'),
    (-0.90, 'disponible disponibles prêt'),
    (-6.60, '备 備'),
    (-2.95, '准备 準備 具备 准备工作 预备'),
    (-2.55, '备用 储备'),
    (-3.60, '准备好'),
    (-1.65, '配备 完备 备案 备注 筹备'),
    (-2.10, '必备'),
    (-0.80, '设备 設備 装备 备份 已 已经 已有'),
    (-1.05, '已經'),
    (-0.58, '早已 すでに'),
    (-3.90, '준비'),
)
SIGNALS = {
    word: strength
    for strength, words in WORD_GROUPS
    for word in words.split()
}

PRESENT_COPULAS = {'is', 'are', 'am', "'m", '’m', "'re", '’re', "'s", '’s'}
PREPARING = {'prepare', 'prepared', 'preparing'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, previous_raw = ('', '')
    if carry is not None and carry[0] == doc:
        previous, previous_raw = carry[1:]
    raw = prefix.token_strings[-1]
    word = raw.strip()
    lower = word.lower()
    spaced = raw.startswith(' ')
    value = SIGNALS.get(lower, 0.0)

    if lower == 'ready':
        value = -4.7
        if word != lower:
            value = -5.3
            if word.isupper():
                value = -5.0 if spaced else -2.3
        elif previous in PRESENT_COPULAS:
            value = -5.3
        elif previous in {'be', 'been', 'was', 'were', 'not'}:
            value = -5.0
        elif previous in {'get', 'gets', 'getting'}:
            value = -3.8
        elif not spaced and previous in {'al', '.al', '_al'}:
            value = -1.7  # 'already' split before 'ready'.
        elif previous == ').':
            value = -5.5  # The jQuery document-ready idiom.
    elif lower == 'readiness':
        value = -3.2
    elif lower in {'-ready', '_ready'}:
        value = -4.9
    elif lower in {'.ready', '.readystate'}:
        value = -3.9 if lower == '.ready' else -2.6
    elif lower == '-equipped':
        value = -1.2
    elif lower == 'готов':  # Russian ready/prepared stem.
        value = -2.3 if spaced else -1.0
    elif lower == 'подготов':
        value = -0.75
    elif word == '비':
        value = -0.95 if spaced else -2.3
    elif lower == 'able' and not spaced:
        value = 0.0  # An internal English suffix is not the word 'able'.
    elif lower in {'available', 'availability'} and word != lower:
        value *= 0.66
    elif lower == 'availability' and not spaced:
        value = -0.26
    elif lower in {'prepare', 'reserve'} and not spaced:
        value *= 0.6

    if lower == 'available' and spaced and word == lower:
        if previous in {'is', 'are', 'be', 'been', 'being', 'now', 'readily'}:
            value = -1.28
        elif previous in {'the', 'of', 'publicly'}:
            value = -0.88
        elif previous == 'commercially':
            value = -0.63

    # Linking words immediately following a readiness expression.
    if previous in {'ready', '-ready', '_ready', '.ready'}:
        if lower == 'to':
            value -= 2.5 if previous_raw == 'Ready' else 2.0
        elif lower == 'for':
            value -= 1.33
        elif lower == '(function':
            value -= 1.2
    elif lower == 'to':
        if previous in PREPARING or previous == 'eager':
            value -= 0.45
        elif previous in {'available', 'willing'}:
            value -= 0.22
    elif lower == 'for':
        if previous in PREPARING:
            value -= 0.2
        elif previous == 'available':
            value -= 0.08
    elif lower == 'of' and previous in {'availability', 'preparation', 'readiness'}:
        value -= 0.45

    return (doc, lower, raw), float(value)

