programs.sol:
"""A context-opening signal, especially for chat and source-code headers.

Predict negative pulses for chat roles, initial headings, articles, the
'Title' field and code-import headers. Most other initial words give positive
pulses, estimated from their script, case and spacing; digits have individual
calibrations. An uninterrupted repetition of the initial token stays in the
opening state. An initial run of digits keeps a weaker positive pulse.
Distinguish ordinary message endings from tool-block endings.
Elsewhere use a small, briefly decaying baseline. Weaker lexical effects
inside documents are deliberately not reconstructed.
"""
import unicodedata

READS = ()
ARTICLES = {'A', 'An'}
INITIAL_DIGITS = (0.17, 0.05, 0.51, 0.23, 0.21,
                  0.28, 0.27, 0.29, 0.25, 0.39)
PERSONAL_OPENERS = {'I', 'You', 'It'}
QUESTION_OPENERS = {'How', 'Why', 'Who'}
COMMON_SPACED_WORDS = {
    'the', 'a', 'an', 'and', 'or', 'of', 'to', 'in', 'on', 'at', 'for',
    'with', 'by', 'it', 'I', 'The',
}


def opening(token):
    word = token.strip()
    if token == '<|im_start|>':
        return -0.534
    if token == 'Title':
        return -1.04
    if token == 'package':
        return -1.0
    if token in {'import', '#include'}:
        return -0.84
    if token in {'export', 'from', 'using', '<?'}:
        return -0.38
    if token in {'const', 'def', 'class', 'public', 'int', 'function'}:
        return -0.28
    if token and not token.strip('#'):
        return {1: -0.55, 2: -0.75, 3: -0.33}.get(len(token), 0.03)
    if token.startswith(('//', '/*', '#!')):
        return -0.36 if '\n' in token else -0.50
    if token == 'The':
        return -0.52
    if token == 'Welcome':
        return -0.09
    if token in ARTICLES or token in PERSONAL_OPENERS or token == 'There':
        return -0.26
    if token == 'This':
        return -0.40
    if token == 'What':
        return -0.55
    if token in {'In', 'If'} or token in QUESTION_OPENERS:
        return -0.20
    if not word:
        return -0.15 if token.startswith('\n') else 0.01
    if len(token) == 1 and token in '0123456789':
        return INITIAL_DIGITS[int(token)]
    if word.isdigit():
        return 0.20
    if token == '.':
        return -0.18
    if token in {',', ':'}:
        return -0.07
    if token == ' (':
        return -0.03
    if word in {'.', ',', ':'}:
        return 0.0
    if len(word) == 1 and word.isascii() and word.isalpha():
        return -0.08 if word.isupper() else 0.0
    if token[0].isspace() and word in COMMON_SPACED_WORDS:
        return 0.01
    if any('CJK' in unicodedata.name(c, '') for c in word):
        return 0.30
    if word.isalpha():
        return 0.17 if word.isascii() and word.islower() else 0.24
    if '\ufffd' in token:
        return 0.30
    return 0.10


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    digit = len(token) == 1 and token in '0123456789'
    if carry is None or carry[0] != doc:
        position, previous, repeating = 0, '', True
        number = digit
    else:
        position, previous = carry[1] + 1, carry[2]
        repeating = carry[3] and token == previous
        number = carry[4] and digit
    value = 0.003 + 0.035 / (1.0 + position)
    if position > 20:
        value = 0.004
    if repeating:
        value = opening(token)
    elif number:
        if position == 1:
            value = 0.5 * INITIAL_DIGITS[int(token)] + 0.01
        else:
            value = 0.07
    elif previous == '<|im_start|>':
        if token == 'assistant':
            value = -0.97 if position == 1 else -0.68
        elif token == 'user':
            value = -0.68 if position == 1 else -0.30
    elif token == '<|im_start|>':
        value = 0.03
    elif token == '<|im_end|>':
        if previous == '</tool_response>':
            value = -0.065
        elif previous == '</tool_call>':
            value = -0.017
        else:
            value = 0.16
    elif token in {'<think>', '<tool_call>'}:
        value = 0.105
    elif token in {'</think>', '</tool_call>'}:
        value = -0.045
    return (doc, position, token, repeating, number), float(value)

programs.luna:
"""This is a sparse text heuristic for the component.

It responds strongly when a chat speaker label opens a message, and uses
document-opening cues for common openers, punctuation and numbers. It also
responds positively to the recurring word stem “root” and, more weakly, to
letter-bearing tokens (especially non-ASCII letters).
"""

READS = ()
NEGATIVE_OPENERS = {"The", "This", "A", "I"}


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    current = tokens[-1]
    previous = tokens[-2] if len(tokens) > 1 else ""

    if previous == "<|im_start|>":
        if current == "assistant":
            return None, -0.68
        if current == "user":
            return None, -0.47

    docs = prefix.document_ids
    starts_document = len(docs) == 1 or docs[-1] != docs[-2]
    if starts_document:
        if current in NEGATIVE_OPENERS:
            return None, -0.43
        if current == "#":
            return None, -0.55
        if current == ".":
            return None, -0.18
        if current.isdigit():
            return None, 0.19
        return None, 0.077

    if current.strip().casefold() == "assistant":
        return None, -0.20
    if "root" in current.casefold():
        return None, 0.20
    if any(ord(char) > 127 and char.isalpha() for char in current):
        return None, 0.014
    if any(char.isalpha() for char in current):
        return None, 0.0056
    return None, 0.0025

programs.sol:
"""A token-spelling detector for products, in commerce and mathematics.

English 'product(s)' and several translations are strongest. Product-word
fragments can also fire outside that meaning (e.g. 'duct' in 'conduct').
Goods, systems, and multiplication vocabulary give smaller responses.
The phrase 'product of' extends the response onto 'of'; familiar vector
product modifiers reduce it. Nothing here disambiguates a word's meaning.
"""
READS = ()

# Product names and stems in Germanic, Romance, Slavic and other languages.
PRODUCT_NAMES = {
    'produk': 3.1, 'produkt': 3.2, 'produkte': 4.5,
    'produktów': 3.3,
    'producto': 3.6, 'productos': 3.7,
    'produto': 3.1, 'produtos': 2.7,
    'produit': 1.4, 'produits': 2.2,
    'продук': 3.3, 'продуктов': 3.0, 'продукции': 2.2,
    'товар': 1.1, 'товаров': 2.3,
    'ürün': 2.6, 'ürünler': 2.5, '제품': 3.2,
}
# Goods, food, articles, works, and the characters shared by those names.
EAST_ASIAN_GOODS = {
    '品': 3.5, '商品': 1.6, '的商品': 1.6,
    '食品': 1.5, '用品': 2.2, '新品': 2.5, '极品': 1.3,
    '制品': 3.1, '成品': 2.3, '药品': 1.2, '毒品': 1.3,
    '作品': 0.9, '的作品': 1.0, '礼品': 0.7,
    '产': 0.9, '產': 0.9, '産': 0.8, '품': 1.5,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    spelling = token.strip().lstrip('._(<[/\\-')
    word = spelling.lower()
    is_product = word in {'product', 'products'}

    if is_product:
        plural = word == 'products'
        value = 5.45 if plural else 5.65
        if spelling[:1].isupper():
            value = 5.9
        if token.startswith(('_', '(', '<')):
            value = 3.1 if plural else 4.0
        elif token.startswith('-'):
            value = 6.4
        elif plural and not token[:1].isspace():
            value = 4.5
        elif spelling.isupper():
            value = 5.3
        if previous == 'dot':
            value = 3.4
        elif previous in {'cross', 'scalar'}:
            value = 4.7
        elif previous == 'inner':
            value = 4.2
    elif word in PRODUCT_NAMES:
        value = PRODUCT_NAMES[word]
        if spelling == 'Produk':
            value = 4.0
        elif spelling == 'Produto':
            value = 2.1
    elif word in {'productive', 'productivity', 'prod'}:
        value = 1.9
    elif word == 'duct':
        value = 1.0 if token[:1].isspace() else (1.65 if spelling.isupper() else 2.0)
    elif word in {'ductive', 'duto'}:
        value = 1.1 if word == 'ductive' else 2.0
    elif word == 'otti' and previous == 'prod':
        value = 2.5
    elif word in {'产品', '產品', '的产品', '新产品'}:
        value = 5.1
    elif word == '产品的':
        value = 4.6
    elif '产品' in word or '產品' in word or word == '产物':
        value = 2.7
    elif word in EAST_ASIAN_GOODS:
        value = EAST_ASIAN_GOODS[word]
    elif word == 'goods':
        value = 2.5
    elif word in {'merchandise', 'commodities'}:
        value = 1.2 if word == 'merchandise' else 0.9
    elif word in {'system', 'systems', 'систем', '系统', '系統', '제도'}:
        value = 0.7
    elif word == 'frac':
        value = 0.78 if token == 'frac' else 0.2
    elif word in {'derivative', 'derivatives', 'multiplication'}:
        value = 0.85
    elif word in {'multiply', 'multiplying', 'multiplied'}:
        value = {'multiply': 1.2, 'multiplying': 1.5, 'multiplied': 0.65}[word]
    elif word in {'lication', 'lying', 'licative'} and previous in {'multip', 'ultip'}:
        value = 1.2
    elif word in {'乘', '积', '積', '∏'}:
        value = 2.3 if word == '∏' else 1.3
    elif word in {'food', 'foods', 'beverage', 'beverages'}:
        value = 0.75
    elif word in {'drug', 'drugs', 'drink', 'drinks'}:
        value = 0.5
    elif word == 'of' and previous in {'product', 'products'}:
        value = 2.35
    else:
        value = 0.0
    return (doc, word), value

programs.haiku:
"""Component layers.0.mlp.down_proj:1814: a "product" word detector.

It fires on the token that is the word "product" (or "products"), and on its
translations and close relatives, and not on the rest of the text. Its activation
depends only on the current token, so the program looks at nothing else:

- ~5.5 on the word itself: " product", " products", "Product", "PRODUCT", and
  Chinese 产品 / 產品 (the English 'product' word, in any capitalisation or spacing).
- ~2.5 on other product-like words: " goods", " produk" / "produto" / "Produkte" /
  продукции-type forms, the "duct" piece of a split "product", and food (食品, 农产品).
- ~0.8 on a few weaker related words: "system(s)", "food", "derivative",
  "multiply", "drink", "beverage", "drug", "frac", and 系统 / 系統.
- 0 everywhere else. Words like "production", "produce", "produced" do not fire.

Main idea: the component reads "this token names a product (goods)", and the
predicted activation is a graded score for how strongly the token does so.
"""

import re

READS = ()

PRODUCT_WORDS = {"product", "products"}
PRODUCT_CHARS = {"产品", "產品"}
RELATED_WORDS = {
    "goods", "produk", "produkt", "produto", "produkte", "produkty",
    "productos", "duct", "prod",
}
RELATED_PARTS = ("продукт", "продукц", "食品", "农产品")
WEAK_WORDS = {
    "system", "systems", "food", "foods", "derivative", "derivatives",
    "multiply", "multiplying", "drink", "beverage", "drug", "frac",
}
WEAK_PARTS = ("系统", "系統")


def _word(token):
    """The token with spaces and punctuation stripped, lowercased."""
    return re.sub(r"\W", "", token.lower())


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = _word(token)
    if word in PRODUCT_WORDS or token in PRODUCT_CHARS:
        value = 5.5
    elif word in RELATED_WORDS or any(p in token for p in RELATED_PARTS):
        value = 2.5
    elif word in WEAK_WORDS or any(p in token for p in WEAK_PARTS):
        value = 0.8
    else:
        value = 0.0
    return carry, value

programs.luna:
"""Predict sparse responses to product, system, and a few related words.

Product terms are the strongest cues; system terms are usually much weaker.
"""

READS = ()

PRODUCTS = ("product", "goods", "食品", "產品", "产品", "商品", "продук")
SYSTEMS = ("system", "систем", "система", "系統", "系统", "제도")
RELATED = ("derivative", "gift", "arom")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lower()
    doc = prefix.document_ids[-1]
    old = "" if carry is None or carry[0] != doc else carry[1]
    word = token.strip() if token[:1].isspace() else old + token
    low = token.strip()

    if "продук" in word or "продук" in low:
        value = 3.0
    elif "食品" in word or "食品" in low:
        value = 1.2
    elif "商品" in word or "商品" in low:
        value = 1.6
    elif any(term in word or term in low for term in PRODUCTS):
        value = 5.2 if any(term in word or term in low
                            for term in ("product", "產品", "产品")) else 2.6
    elif any(term in word or term in low for term in SYSTEMS):
        value = 0.7
    elif any(term in word or term in low for term in RELATED):
        value = 0.8
    else:
        value = 0.0

    pieces = token.split()
    tail = pieces[-1] if pieces else ""
    if token[:1].isspace() or any(ch.isspace() for ch in token):
        tail = tail[-40:]
    else:
        tail = (old + token)[-40:]
    return (doc, tail), float(0.22 * value)

programs.sol:
"""Partial lexical explanation, not a general semantic detector.

The rare largest positives complete separately tokenized East Asian words,
mostly 写真 (photograph) and some technical nouns. Smaller responses depend
on selected quantity words, physical descriptors, noun-forming characters,
grammatical particles, and message boundaries. Levels approximate training
averages; background responses are shrunk by 0.8 after a training-only
output-sensitivity check.
Unlisted tokens get zero; much weak context-specific detail is lost.
The previous token and a short text tail reset between documents.
This captures only a small fraction of the component's activation variance.
"""
READS = ()

# Compound word, final token, strength. Only split completions are boosted.
COMPOUNDS = (
    ('写真', '真', .73),       # photograph
    ('寫真', '真', .70),       # traditional spelling
    ('字典', '典', .73),       # dictionary
    ('脚本', '本', .65),       # script
    ('字节', '节', .77),       # byte
    ('基因组', '组', .75),     # genome
    ('染色体', '体', 1.1),     # chromosome
    ('电解质', '质', .77),     # electrolyte
    ('胶质', '质', .77),       # glia
    ('脉动', '动', .80),       # pulsation
)

# Small, named word classes. Only space-prefixed tokens match.
WORD_CLASSES = (
    ({'much'}, .11),
    (set('many numerous several few'.split()), .05),
    ({'more', 'most'}, .027),
    (set('only least either neither exactly'.split()), -.07),
    ({'soft'}, -.18),
    (set('hard light heavy long straight deep dark bright cold warm '
         'rough delicate tender'.split()), -.065),
    ({'public', 'free', 'common'}, .06),
    ({'space', 'volume', 'width'}, .06),
    ({'using', 'used'}, .033),
    ({'first', 'after', 'future', 'current'}, -.045),
)

PHRASES = {
    ('at', 'least'): -.125,
    ('at', 'all'): -.113,
    ('not', 'only'): -.111,
    ('not', 'just'): -.117,
    ('how', 'much'): .164,
    ('how', 'many'): .093,
    ('other', 'hand'): .17,
    ('can', 'be'): -.043,
    ('able', 'to'): -.075,
    ('due', 'to'): -.059,
    ('going', 'to'): -.059,
    ('known', 'as'): -.076,
    ('et', 'al'): -.062,
}

# Prepositions have different effects on the following definite article.
ARTICLE_POSITIVE = {'to', 'with', 'into', 'between', 'among', 'as'}
ARTICLE_NEGATIVE = {'in', 'at', 'for', 'during', 'after'}
DEICTIC_CONTRACTIONS = {'that', 'there', 'here', 'what'}
HUMAN_PLURALS = {'men', 'women', 'children'}

CHARACTER_CLASSES = (
    (set('软柔滑硬粗细深浅淺冷暖暗空'), -.18),  # physical qualities
    (set('嫩浓'), -.32),                       # tender; concentrated
    (set('大长長'), -.075),                    # big; long
    (set('体體型器管量质質组'), .12),           # technical noun morphemes
    (set('度点节節'), .08),                    # measurement/unit morphemes
)

# Literal grammatical particles, plus 真 ('true') outside photograph compounds.
PARTICLES = {'に': -.096, 'で': .055, '的': .026, '和': -.052}
TRUTH_CHARACTER = {'真': .15}
MARKERS = {
    '<|im_start|>': .070,
    '<|im_end|>': .058,
    '<tool_response>': -.088,
    '</tool_response>': -.167,
    '</think>': -.116,
}


def english_word_value(token, previous):
    """Word classes, spelling endings, and short grammatical expressions."""
    value = 0.0
    previous_word = previous.strip().lower()
    word = token.strip().lower()
    if word.isalpha():
        if word.endswith(('tion', 'ment', 'ness')):
            value = .009
        elif word.endswith(('less', 'ism')):
            value = -.028
    if word == 'the':
        if previous_word in ARTICLE_POSITIVE:
            value = .030
        elif previous_word in ARTICLE_NEGATIVE:
            value = -.018
        elif previous_word == 'all':
            value = -.060
        elif previous.rstrip().endswith(','):
            value = .017
    elif word == 'of':
        if previous_word in {'hundreds', 'thousands', 'millions', 'billions'}:
            value = -.140
        elif previous_word in {'half', 'percent', '%'}:
            value = .090
        elif previous_word in {'number', 'amount', 'pair'}:
            value = .050
        elif previous_word in {'kind', 'type', 'species'}:
            value = -.055
    elif word == 'is' and previous_word in {'there', 'here'}:
        value = -.060
    elif word == 'be':
        if previous_word in {'can', 'cannot'}:
            value = -.040
        elif previous_word in {'will', 'might'}:
            value = .020
    for words, strength in WORD_CLASSES:
        if word in words:
            value = strength
            break
    if previous.startswith(' '):
        value = PHRASES.get((previous.strip().lower(), word), value)
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous, tail = ('', '') if start else carry[1:]
    token = prefix.token_strings[-1]

    value = MARKERS.get(token, PARTICLES.get(token, TRUTH_CHARACTER.get(token, 0.0)))
    if token == '<|im_start|>' and start:
        value = .148
    elif token in {"'s", '’s'}:
        previous_word = previous.strip().lower()
        value = -.014
        if previous_word in DEICTIC_CONTRACTIONS:
            value = -.070
        elif previous_word in HUMAN_PLURALS:
            value = .12
        elif previous_word in {'man', 'woman'}:
            value = .05
    elif token.startswith(' ') and token.strip().isascii():
        value = english_word_value(token, previous)

    for characters, strength in CHARACTER_CLASSES:
        if token in characters:
            value = strength
            break

    # Downweight uncertain background averages, not sharp compound matches.
    value *= 0.8
    text_tail = (tail + token)[-12:]
    for word, ending, strength in COMPOUNDS:
        if token == ending and text_tail.endswith(word):
            value = strength
            break
    return (doc, token, text_tail), value

programs.haiku:
"""Fires on the final character of a two-character Chinese/Japanese noun compound
(写真 photo -> 真, 脚本 script -> 本, 示例 example -> 例, 防火墙 firewall -> 墙), and weakly
on any Chinese/Japanese character that follows another such character.

The component writes a small positive push into the residual stream when the current
token completes one of these compounds. The word list is a few examples, not a full
lexicon; the program is a readable approximation of the component's rare spikes (about +0.5).
"""

READS = ()

COMPOUNDS = {
    "写真", "脚本", "示例", "防火墙", "酵素", "优先级", "多边形", "基因组",
    "字节", "字典", "胶质", "染色体", "绿化", "电解质", "循环", "血统",
    "以太坊", "拓扑", "专项斗争",
}


def _is_kana_or_han(s):
    return len(s) == 1 and ("一" <= s <= "鿿" or "぀" <= s <= "ヿ")


def step(carry, prefix, upstream):
    ids = prefix.document_ids
    cur = prefix.token_strings[-1]
