programs.sol:
"""Predict a signed interaction at token boundaries after an e-like vowel.

Doubled e is negative; other vowels (especially i) and digits are positive.
Long pieces and camelCase word boundaries weaken the response. Kana
rules distinguish doubled e, katakana vowels, and small tsu. Thai rules
recognize a preposed เ followed by vowel or tone marks, retaining it across
one separately tokenized consonant. Bare e at a text start is negative.
Other positions are zero; state resets with the document label.
"""
import math
import unicodedata

READS = ()
E_KANA = 'えけげせぜてでねへべぺめれゑエケゲセゼテデネヘベペメレヱ'


def letter(char):
    if not char:
        return ''
    return unicodedata.normalize('NFD', char.lower())[0]


def response(previous, text):
    if not text:
        return 0.0
    if not previous or previous == '<|endoftext|>':
        return -2.0 if text in ('e', 'E') else 0.0
    first = letter(text[0])
    end = letter(previous[-1])
    if previous[-1] in E_KANA:
        strength = math.exp(-0.3 * max(0, len(previous.strip()) - 2))
        size = len(text)
        # Hiragana-to-katakana switches usually start a new word.
        if previous[-1] <= '\u309f' and '\u30a0' <= first <= '\u30ff':
            return 0.0
        if first in 'えエ':
            return -2.4 * strength
        if first in 'アイ':
            value = 0.6 if first == 'ア' else 0.9
            return value * strength * math.exp(-0.4 * max(0, size - 1))
        if first in 'っッ':
            return 1.6 * strength * math.exp(-0.9 * max(0, size - 1))
        return 0.0
    if end in 'eеεɛ':
        previous_size = len(previous.strip())
        size = len(text.strip())
        strength = math.exp(-0.3 * max(0, previous_size - 3))
        if first in 'eеε':
            value = -2.4 * math.exp(-0.2 * max(0, size - 2))
            if size <= 2:
                strength = math.exp(-0.15 * max(0, previous_size - 4))
            if text.lower().startswith('ee'):
                value *= 0.3
        elif first in 'iиι':
            value = 1.5 * math.exp(-0.15 * max(0, size - 3))
            if size == 1:
                value *= 0.75
            elif letter(text[1]) in 'lrлр':
                value += 0.35
        elif first in 'aаα':
            value = 0.65
        elif first in 'uυyу':
            value = 0.75
        elif first in 'oоο':
            value = 0.35
        elif text[0].isdigit():
            value = 0.85
        else:
            return 0.0
        if first not in 'eеεiиι':
            value *= math.exp(-0.15 * max(0, size - 3))
        # A case change marks a new word in a camelCase identifier.
        if previous[-1].islower() and text[0].isupper():
            strength *= 0.15
        return strength * value
    # Thai writes this vowel before the syllable's consonant.
    start = previous.rfind('เ')
    syllable = previous[start:] if start >= 0 else ''
    if syllable and len(syllable) <= 3:
        if text[0] in 'ิีึื':
            if text.startswith(('ือ', 'ีย')):
                return 0.15
            if len(text) == 1 or text[1] in '่้๊๋':
                return 2.7
            return 1.2 if len(text) == 2 else 0.5
        if text[0] in '่้๊๋':
            return 0.5
        if syllable == 'เ' and '\u0e01' <= text[0] <= '\u0e2e':
            return 1.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = response(previous, text)
    # Retain a Thai preposed vowel when its consonant was a separate token.
    if previous.strip() == 'เ' and len(text) == 1:
        if '\u0e01' <= text <= '\u0e2e':
            text = 'เ' + text
    return (doc, text), float(value)

