programs.haiku:
"""Coordinating conjunctions ("and", "or", "und", "et", "和", ...) in many languages.

The component writes a large positive value on the word that joins two items or
two clauses in running text: "bread, and butter", "X or Y", "Brot und Butter",
"pain et beurre", "хлеб и масло", "管理和服务". It is strongest after a comma
(joining whole clauses) and weaker after a digit or inside a fixed phrase such as
"between 3 and 5" or "one or more", where it stays near zero. Chinese compounds
that end in 和 (e.g. 管理和, "management and") fire the most.
"""

READS = ()

# Conjunction words written with a leading space (a whole word, not a word piece).
SPACED = {
    "and", "And", "or", "Or", "und", "Und", "oder", "et", "Et", "ou", "og", "och",
    "eller", "nor", "и", "или", "і", "و", "أو", "và", "hoặc", "ve", "sowie", "oraz", "şi",
}
# Chinese, Japanese and Korean conjunctions need no leading space.
UNSPACED = {"和", "或", "或者", "及", "以及", "と", "や", "과", "와", "고", "하고"}
# "or" is weaker than "and" in the same spot.
OR_WORDS = {"or", "Or", "oder", "ou", "или", "或", "或者", "nor", "eller"}
# Spanish/Portuguese "y"/"e" join nouns in running text, but also appear as math variables.
WORD_CONJUNCTIONS = {"y", "e"}
DIGITS = set("0123456789")
# Fixed phrases where "and"/"or" is not a joiner: "between 3 and 5", "one or more".
FIXED_BEFORE = {"between", "one", "more", "than", "whether", "either"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    token = raw.strip()
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip() if same_doc else ""
    is_word = raw.startswith(" ") and (token in SPACED or (token in WORD_CONJUNCTIONS and len(prev) > 2 and prev.isalpha()))
    if is_word or token in UNSPACED:
        value = 0.7 if token in OR_WORDS else 1.0
        if prev == ",":
            value *= 1.5
        elif prev[-1:] in DIGITS:
            value *= 0.6
        recent = {s.strip() for s in prefix.token_strings[-4:]}
        if recent & FIXED_BEFORE:
            value = 0.0
        return carry, value
    # Chinese words that carry 和 ("and") as a suffix, e.g. 管理和 "management and".
    if len(token) >= 2 and token.endswith("和"):
        return carry, 7.0
    if len(token) >= 2 and token.startswith("和"):
        return carry, 1.5
    return carry, 0.0

"""layers.0.mlp.down_proj:1821 as a feelings / announcements / knowing detector.

This component fires on a small set of words that express pleasure, pride or luck
("delighted", "pleased", "proud", "lucky", "glad", "happy", "excited"), on words about
announcements, occasions and honour ("announced", "announcement", "occasion", "news",
"honor", "celebrations"), and on forms of "know". It fires most strongly on the word that
completes a feeling: "excited [to]", "proud [of]", "pleased [with]", "glad [that]". Each
such word gets a fixed strength, read off the training data. Everything else is near 0,
apart from a weak background on "to" (mildly positive after willingness words such as
"willing" or "opportunity", mildly negative after "likely" or "began").
"""
READS = ()
FEELING = {
    "delighted": 1.4, "fortunate": 1.4, "lucky": 1.2, "luck": 0.9, "pleased": 1.1, "privileged": 1.5,
    "thrilled": 1.0, "saddened": 1.1, "disappointed": 0.9, "proud": 0.9, "glad": 0.8,
    "honored": 0.75, "honoured": 0.75, "excited": 0.6, "surprised": 0.5, "shocked": 0.5,
    "grateful": 0.5, "sorry": 0.5, "happy": 0.35, "angry": 0.35, "sad": 0.2, "幸": 1.2, "高兴": 1.0,
}
NEWS = {
    "announce": 1.5, "announced": 1.1, "announces": 1.0, "announcement": 1.2, "announcing": 1.2,
    "occasion": 0.95, "occasions": 1.0, "honor": 0.8, "honour": 0.75, "pleasure": 1.0,
    "celebrations": 0.8, "celebration": 0.5, "celebrating": 0.5, "privilege": 0.75,
    "news": 0.6, "welcome": 0.55, "opportunity": 0.45, "joy": 0.5, "cheer": 0.6,
    "coincidence": 0.85, "anniversary": 0.4,
}
KNOW = {"know": 0.8, "knew": 0.75, "knows": 0.65, "knowing": 0.75, "known": 0.3, "knowledge": 0.25}
WORD = {**FEELING, **NEWS, **KNOW}
AFTER = {" to": 2.5, " of": 1.0, " with": 1.0, " for": 0.7, " about": 0.4, " that": 0.3}
# 'to' after words of willingness or permission is mildly positive; after aspect/raising verbs, mildly negative
WILLING = {"willing", "sure", "free", "permission", "chance", "eager", "opportunity", "enough", "welcome"}
RAISING = {"likely", "began", "begin", "started", "starts", "designed", "found", "attempt", "attempts",
           "tend", "ability", "appears", "seems", "appeared"}

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    word = tok.strip().lower()
    if word in WORD and (tok[:1] == " " or tok[:1].isupper() or not tok[:1].isascii()):
        return carry, WORD[word]
    if prev in FEELING and tok in AFTER:
        return carry, AFTER[tok]
    if prev in NEWS and tok in AFTER:
        return carry, 0.7 * AFTER[tok]
    if tok == " to":
        if prev in WILLING:
            return carry, 0.3
        if prev in RAISING:
            return carry, -0.15
    return carry, 0.0

