"""Approximate the component's word-sensitive response to English infinitives.

When a listed verb follows "to", perception, knowledge, search and acquisition
verbs get a stronger negative value, other listed verbs a weaker one, and a few
common verbs such as "be" or "have" a positive value. Everything else is zero.
"""
import re

READS = ()

STRONG_VERBS = {
    "see", "understand", "find", "determine", "get", "know", "gain",
    "ensure", "obtain", "discover", "assess", "identify", "learn",
}
OTHER_VERBS = {
    "estimate", "prevent", "avoid", "confirm", "observe", "investigate",
    "verify", "reach", "try", "calculate", "derive", "form", "make",
    "explore", "improve", "answer", "detect", "address", "measure", "check",
    "establish", "protect", "solve", "prove", "remove", "design", "create",
    "develop", "convert", "build", "reduce", "select", "read",
}
LINKING_VERBS = {"be", "have", "say", "include", "thank", "follow"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    before = "" if carry is None or carry[0] != document else carry[1]
    word = token.strip().lower()

    if re.search(r"\bto\s*$", before, re.IGNORECASE):
        if word in STRONG_VERBS:
            value = -1.8
        elif word in OTHER_VERBS:
            value = -0.9
        elif word in LINKING_VERBS:
            value = 0.9
        else:
