             'disagreed', 'agreement', 'consistent'}
VARIATION = {'difference', 'differences', 'differ', 'differs', 'differed',
             'vary', 'varies', 'varied', 'varying', 'differently'}
MANNER = {'way', 'manner', 'approach', 'direction'}
MEASURE = {'level', 'number', 'result', 'amount'}
ABSTRACT_FORMS = {'form', 'formula', 'rule', 'solution', 'idea'}
PUBLIC_AFFAIRS = {'election', 'assembly', 'public', 'meeting', 'services'}
RELATIONAL_PREPOSITIONS = {
    'between': -0.07, 'among': -0.20, 'across': -0.20,
    'during': -0.09, 'throughout': -0.20, 'without': -0.11,
}
SAME_COMPLEMENTS = {
    'thing': -3.25, 'things': -2.00, 'as': -2.15,
    'here': -2.40, 'with': -2.30, 'across': -2.30,
    'throughout': -1.70, 'among': -1.70, 'in': -0.83,
    'old': -1.75, 'for': -1.40, 'day': -1.50,
    'year': -1.30, 'time': -0.26,
