    'same': -1.72, 'general': -1.00, 'similar': -0.96,
    'common': -0.65, 'normal': -0.55, 'standard': -0.65,
}


def phrase_value(previous, word):
    value = DESCRIPTORS.get(previous, RELATIONAL_PREPOSITIONS.get(word, 0.0))
    if previous == 'same':
        if word.startswith('-'):
            return -1.65
        if word in MANNER or word in MEASURE:
            return -1.00
        return SAME_COMPLEMENTS.get(word, value)
    if previous == 'different':
        if word in {'from', 'than'}: return -1.65
        if word in {'across', 'among'}: return -1.20
        if word in {'in', 'to'}: return -0.62
        if word in MANNER: return -0.50
    if previous == 'similar':
        if word == 'to': return -0.68
        if word in {'with', 'in'}: return -0.80
        if word == 'across': return -1.40
        if word in MANNER: return -0.75
    if previous == 'general':
        if word in ABSTRACT_FORMS or word in PUBLIC_AFFAIRS: return -0.90
        if word in {'manager', 'management'}: return -1.35
    if previous == 'common':
        if word == 'law': return -1.50
        if word in {'sense', 'stock', 'with'}: return -1.05
        if word == 'denominator': return -0.85
    if previous == 'normal' and word in {'form', 'mode', 'course', 'operation'}:
        return -1.05
    if previous in AGREEMENT:
        if word == 'with': return -0.80
        if word == 'across': return -1.60
    if previous == 'accordance' and word == 'with': return -0.35
    if previous in VARIATION and word in {'from', 'between', 'among', 'across'}:
        return -0.85
