        value = -1.00 if 'same' in recent[-2:] else -0.55
    if first:
        value = DOCUMENT_INITIAL.get(word, value)
    recent = (recent + (word,))[-4:] if word.strip('-').isalpha() else ()
    return (doc, word, recent), value

"""A token's written size and word shape predict this component.

Short words, digits and punctuation are quiet. Long alphabetic tokens are
positive, with a lower length threshold for Chinese characters and Japanese
syllabic writing. English grammatical words and code keywords stay quiet;
grammatical endings contribute less than the rest of a word. Vowel groups,
with a correction for silent final e, approximate syllable count. Long repeated
separator runs and chat delimiters get structural responses. No context is used.
"""
import re
import math
from functools import lru_cache
import unicodedata

READS = ()

FUNCTION_WORDS = set("""
a an the and or but if as of to in on at by for from with without within
into onto upon over under out up down off be been being is are was were am
do does did have has had can could will would may might must shall should
not no so than that this these those it its he him his she her hers they them
their we us our you your who whom whose what which when where why how any all
some each every either neither both such much more most other another only
very also then there here because before after between through during while
since until unless although whether against towards instead rather however
therefore thus hence otherwise nevertheless alternatively please
""".split())
CODE_KEYWORDS = set("""
return import include define pragma assert throw throws catch try else finally
switch case break continue yield async await public private protected static
void const let var class struct enum typedef namespace using new delete
extends implements package
""".split())
DELIMITERS = {
    '<|im_start|>': 2.015, '<|im_end|>': 1.445,
    '<think>': 1.899, '</think>': 2.481, '<|endoftext|>': 0.026,
    '<tool_call>': -0.174, '</tool_call>': 0.279,
    '<tool_response>': 1.377, '</tool_response>': 1.621,
}


def script(c):
    name = unicodedata.name(c, '')
    if 'LATIN' in name:
        return 'latin'
    if 'CYRILLIC' in name:
        return 'cyrillic'
    if 'CJK' in name or 'IDEOGRAPH' in name:
        return 'cjk'
    if 'HIRAGANA' in name or 'KATAKANA' in name:
        return 'kana'
    return 'other'


@lru_cache(maxsize=16384)
def response(token):
    if token in DELIMITERS:
        return DELIMITERS[token]
    text = token.strip()
    letters = ''.join(c for c in text if c.isalpha())
    n = len(letters)
    if not n:
        if len(text) >= 4 and len(set(text)) == 1 and text[0] in '-=_.*#~':
            return min(1.8, 0.60 * max(math.log2(len(text))-2, 0))
        return 0.007
    counts = dict.fromkeys(('latin', 'cyrillic', 'cjk', 'kana', 'other'), 0)
    for c in letters:
        counts[script(c)] += 1
    kind = max(counts, key=counts.get)
    if kind == 'cjk':
        return -0.057 + 1.370 * min(n-1, 1) + 0.519 * max(n-2, 0)
    if kind == 'kana':
        return -0.070 + 0.460 * (n-1) - 0.019 * max(n-3, 0)
    if kind == 'cyrillic':
        return -0.075 + 0.064 * (n-1) + 0.253 * max(n-3, 0)
    if kind == 'other':
        return -0.006 + 0.200 * (n-1) + 0.138 * max(n-3, 0)

    word = letters.lower()
    if word in FUNCTION_WORDS:
        return 0.011
    if word in CODE_KEYWORDS:
        return 0.152
    # Written length, plus an approximate spoken syllable count.
    syllables = len(re.findall('[aeiouy]+', word))
    if n > 3 and word.endswith('e') and not word.endswith(('le', 'ee', 'ye', 'oe')):
        syllables -= 1
    value = (-0.284 + 0.275 * max(n-4, 0) - 0.105 * max(n-8, 0)
             - 0.117 * max(n-12, 0) + 0.245 * max(syllables, 1))
    # Grammatical endings add less than their literal character count.
    if n > 5 and word.endswith('ing') and word not in {
            'nothing', 'anything', 'something', 'everything'}:
        value -= 0.682
    if n > 5 and word.endswith('ed'):
        value -= 0.380
    if n > 4 and word.endswith('ly'):
        value -= 0.350
    if n > 5 and word.endswith('s'):
        value -= 0.176
    return float(value)


def step(carry, prefix, upstream):
    return None, float(response(prefix.token_strings[-1]))

