    elif word.endswith('Exception') and lower != 'exception':
        value = 0.35
    elif lower == 'readme':
        value = 0.41 if spaced else 0.60
    elif word == 'FAILED':
        value = 0.40
    elif lower == 'debug':
        value = 0.39 if raw.startswith('-') else 0.08
    elif lower.startswith('ошиб'):
