HARDWARE = {
    'sensor', 'sensors', 'Sensor', 'Sensors', 'hardware', 'Hardware',
    'firmware', 'wiring', 'PCB', 'IoT', 'Raspberry',
}
CONTROL_CIRCUITS = {
