    'controller', 'controllers', 'Controller', 'counter', 'Counter',
    'timer', 'Timer', 'embedded', 'Embedded', 'schematic', 'amplifier',
    'electronic', 'electronics', 'Electronics', 'circuits', 'circuit',
    'automation', 'components', 'semiconductor', 'silicon', 'robot', 'robotics',
}
HARDWARE_BUILDING = {
    'servo', 'stepper', 'solder', 'soldering', 'accelerometer',
    'keypad', 'backlight', 'chipset', 'peripherals',
}
SYSTEM_SOFTWARE = {
    'library', 'libraries', 'graphics', 'driver', 'drivers', 'Driver',
    'kernel', 'interface', 'Interface', 'SDK', 'sdk', 'setup', 'delay',
