CAMERA_CONSOLE_BRANDS = {
    'Sony', 'Canon', 'Nikon', 'Nintendo', 'PlayStation', 'Xbox', 'Sega',
}
C_MEMORY = {'strlen', 'strcmp', 'strcpy', 'memset', 'memcpy'}
C_SYSTEMS = {
    'printf', 'scanf', 'fopen', 'perror', 'typedef', 'unsigned', 'extern', 'feof', 'srand',
}
# Hardware, sensor, chip, integrated circuit, microcontroller, serial, interrupt.
CHINESE_HARDWARE = {'硬件', '传感器', '芯片', '集成电路', '单片机', '串口', '中断'}
# Control, electronics, IoT, buzzer/pushbutton/chip fragments.
CHINESE_ELECTRONICS = {'控制', '控', '电子', '物联网', '蜂', '按键', '芯'}

# Word class, base activation, contextual boost, starts electronics context.
GROUPS = (
    (FIRMWARE_CONFIG, 3.01, 0.48, True),
    ({'lcd', 'irq', 'dma'}, 1.58, 0.22, True),
    ({'asonic', 'ystick', 'adget'}, 1.11, 0.0, False),
    ({'millis', 'Millis'}, 1.12, 0.08, False),
    (HARDWARE_BUILDING, 0.91, 0.24, True),
    ({'Arduino'}, 2.4, 0.44, True),
    ({'USART', 'GPIO', 'gpio', 'InitStructure'}, 2.12, 0.39, True),
    (IO_DEVICES, 0.85, 0.58, True),
    (CAMERA_CONSOLE_BRANDS, 0.50, 0.0, False),
    (HARDWARE, 0.59, 0.23, True),
    (CONTROL_CIRCUITS, 0.29, 0.49, False),
    (SYSTEM_SOFTWARE, 0.23, 0.52, False),
    (C_MEMORY, 0.62, 0.0, False),
    (C_SYSTEMS, 0.37, 0.25, False),
)
AMBIGUOUS = {
    'pin': (0.38, 1.46), 'analog': (0.74, 0.61), 'board': (0.24, 1.14),
    'chip': (0.25, 0.18), 'sketch': (0.48, 0.34), 'digital': (0.07, 0.56),
    'IDE': (0.24, 0.59), 'display': (0.18, 0.39),
}


def response(token):
    s = token.strip()
    word = s.lstrip('(_./')
    if word == 'led':
        return (0.2, 0.17, False) if token != s else (-0.04, 0.19, False)
    if word in {'Pin', 'PIN'}:
        return 0.38, 1.46, False
    if s in CHINESE_HARDWARE:
        return 0.91, 0.24, True
    if s in CHINESE_ELECTRONICS:
        return 0.4, 0.0, False
    if s in {'.println', '.sleep', '.begin', '.read'}:
        return 0.34, 1.21, False
    if s in FIRMWARE_IDENTIFIERS:
        return 1.24, 0.48, True
    if s == 'serial':
        return 0.67, 0.54, False
    if word in {'pins', 'boards', 'chips', 'displays'}:
        word = word[:-1]
    if word in AMBIGUOUS:
        base, boost = AMBIGUOUS[word]
        return base, boost, False
    if token == 'bed':
        return 0.67, 0.0, False
    if s in {'#include', '#define', '#ifdef', '#ifndef', '#endif', '.h'}:
        return 0.56, 0.26, False
    if s == '.rs':
        return 0.39, 0.0, False
    if s == '<tool_call>':
        return 0.16, 0.0, False
    if s in {'</tool_call>', '<tool_response>', '</tool_response>'}:
        return -0.12, 0.0, False
    for words, base, boost, marker in GROUPS:
        if word in words:
            return base, boost, marker
    return 0.0, 0.04, False


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = 0.0 if carry is None or carry[0] != doc else carry[1]
    base, boost, marker = response(prefix.token_strings[-1])
    value = base + boost * recent
    recent = 1.0 if marker else 0.96 * recent
    return (doc, recent), float(value)

