programs.sol:
"""A lexical help/assistance signal, not a general helpfulness classifier.

Help inflections are strongest; translations, helper names, and related
usefulness/action words are weaker. Previous-token article, need, and modal
cues adjust 'help'. Selected recipients and word endings following help also
respond. Unlisted cases are zero; context resets at document boundaries.
"""

READS: tuple[str, ...] = ()

HELP_VERBS = {'help', 'helps', 'helped', 'helping'}
MODALS = {'can', 'could', 'will', 'would', 'may', 'might', 'must', 'shall'}
DETERMINERS = {'a', 'an', 'the', 'some', 'any', 'my', 'your', 'his', 'her',
               'our', 'their'}
# Help words and stems in Spanish/Portuguese, then other languages.
ROMANCE_HELP = {'ayud', 'ayuda', 'ayudar', 'ajud', 'ajuda', 'ajudar'}
OTHER_ASSISTANCE = {'helfen', 'hilfe', 'helf', 'aider', 'aide', 'aiut',
                    'помощь', 'помощи', 'помощью', 'помощ', 'pomoc',
                    'yardım', 'yardımcı', 'ساعد', 'مساعدة', 'سייע',
                    'עזרה', 'לעזור', '助け', 'ช่วย', '่วย', 'đỡ'}
WORK_VERBS = {'work', 'works', 'worked', 'working'}
USEFUL = {'useful', 'aid', 'aids', 'aided', 'aiding', 'thanks'}
ALLOW = {'allow', 'allows', 'allowed', 'allowing'}
CAUSE = {'cause', 'causes', 'caused', 'causing'}
MAKE = {'make', 'makes', 'made', 'making'}


def lexical_value(raw):
    word = raw.strip().lstrip('._/\\(-').lower()
    if word in HELP_VERBS:
        value = 8.4 if word == 'helps' else 7.7
        if word in {'helped', 'helping'}:
            value = 7.5
        if raw.strip().isupper():
            value = 6.5
        elif word == 'helping' and raw.strip()[:1].isupper():
            value = 6.5
        if raw.strip().startswith(('_', '.', '/')):
            value -= 1.0
        return value
    if word == 'helpful':
        return 2.9
    if word == 'helpless':
        return 1.6
    if word in {'helper', 'helpers'} or word.endswith('helper'):
        return 1.5
    if word in {'assistant', 'assistants'}:
        return 0.65
    if word == 'assistance':
        return 2.1
    if word in {'assist', 'assists', 'assisted', 'assisting'}:
        return 2.1 if raw.startswith(' ') else 1.1
    if word == 'elpers':
        return 1.8
    if word in {'elp', 'elps'}:
        return 3.4  # the distinctive ending of 'help'
    if word == '帮助':
        return 5.1
    if word == '幫助':
        return 4.6
    if '帮助' in word or '幫助' in word:
        return 4.0
    if word == '有助于':
        return 4.1
    if word in {'帮', '幫', '助', '帮忙', '幫忙', '助力'}:
        return 3.3
    if word in {'协助', '協助'}:
        return 3.0
    if word.startswith(('帮', '幫')):
        return 2.5
    if word in {'辅助', '輔助', '借助', '互助', '补助', '自助', '援助'}:
        return 1.5
    if word == 'помог':
        return 4.0
    if word in {'поможет', 'giúp'}:
        return 3.3
    if word in ROMANCE_HELP:
        return 2.7
    if word in OTHER_ASSISTANCE:
        return 1.7
    if word in WORK_VERBS:
        return 0.85
    if word in USEFUL or word in {'有用', '有用的'}:
        if word == 'aid' and not raw.startswith(' '):
            return 0.0  # often just the ending of 'said' or 'paid'
        if raw.strip() == 'AIDS':
            return 0.0
        return 1.0
    if word in ALLOW or word in CAUSE:
        return 0.55
    if word in MAKE:
        return 0.45
    if word == 'used' and raw.startswith(' '):
        return 0.22
    if word in {'用', '利用', '使用'}:
        return 0.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    before = previous.strip().lower()
    word = raw.strip().lower()
    value = lexical_value(raw)
    if word == 'help' and raw.startswith(' '):
        if before in MODALS:
            value = 8.5
        elif before in DETERMINERS:
            value = 6.2
        elif before in {'need', 'needs', 'needed'}:
            value = 5.7
    if before in HELP_VERBS:
        if word == 'me':
            value = 2.2
        elif word in {'you', 'us', 'to', 'of'}:
            value = 1.3
        elif word in {'him', 'her', 'them', 'the', 'a'}:
            value = 1.0
        elif word in {'in', 'with'}:
            value = 0.2
        elif raw in {'ed', 'ing'}:
            value = 5.0
    if before == 'ass' and word in {'isted', 'isting'}:
        value = 1.1
    if before == 'помог' and raw in {'ает', 'ают', 'у', 'ите'}:
        value = 2.0
    if before in {'help', 'helpful'} and raw in {'ful', 'ness'}:
        value = 1.7
    if before == '<|im_start|>' and word == 'assistant':
        value = 0.0  # a chat role label, not an assistant in the text
    return (doc, raw), float(value)

programs.haiku:
"""Layer-0 MLP down_proj component 1830: a "help / assist / enable" verb detector.

The component reads only the current token; no context is needed. It fires when that
token is a verb of helping, assisting or enabling, the kind of verb usually followed by
an object or an infinitive ("help [them] do", "assist [in]", "allow [X] to",
"cause [X] to", "make [X] do", "work [to]", "used [to]"). Its strongest response is to
"help" and its forms (help, helps, helped, helping, helper), then to "assist" and
"assistance". Weaker responses go to causative and enabling verbs (allow, cause, make,
enable) and to a few Chinese verbs of helping, using and enabling (帮助, 协助, 使得,
使, 利用, 用来, 是用来, 带领, 实现), and to "work" and "use". Every other token predicts 0.
"""

READS = ()

HELP = {"help", "helps", "helped", "helping", "helper", "helpers"}
ASSIST = {"assist", "assists", "assisted", "assisting", "assistance"}
MEDIUM = {
    "帮助", "协助", "使得", "使", "利用", "用来", "是用来", "带领", "实现",
    "allow", "allows", "allowed", "allowing",
    "cause", "causes", "caused", "causing",
    "make", "makes", "made", "making",
    "enable", "enables", "enabled",
}
WEAK = {"work", "works", "worked", "working", "use", "used", "uses"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in HELP:
        return None, 8.0
    if word in ASSIST:
        return None, 6.0
    if word in MEDIUM or word in WEAK:
        return None, 0.5
    return None, 0.0

