"""Estimate a sparse help-word signal, plus a few related action words."""
READS = ()

HELP_VERBS = {"help", "helps", "helped", "helping"}
ASSISTING = {"assist", "assists", "assisted", "assisting", "assistance"}
HELP_ADJECTIVES = {"helpful", "helpfulness"}
HELP_NOUNS = {"helper", "helpers"}
AID_FORMS = {"aid", "aids", "aided", "aiding"}
WORK = {"work", "works", "worked", "working"}
MAKE = {"make", "makes", "made", "making"}
CAUSE = {"cause", "causes", "caused", "causing"}
ALLOW = {"allow", "allows", "allowed", "allowing"}
ENABLE = {"enable", "enables", "enabled", "enabling"}
LEAD = {"lead", "leads", "led", "leading"}
