CHINESE = {
    "帮助", "協助", "协助", "援助", "陪", "補", "补", "利用", "带领",
    "帶領", "负责", "負責",
}


def score(word):
    if word in HELP_VERBS:
        return 6.9
    if word.startswith("helpful"):
        return 2.8
    if word.startswith("helper"):
        return 0.85
    if word.startswith("help"):
        return 1.1
    if word in ASSISTING:
        return 1.8
    if word in AID_FORMS:
        return 0.8
    if word in WORK:
        return 0.7
    if word in MAKE:
        return 0.4
    if word in CAUSE:
        return 0.55
    if word in ALLOW:
        return 0.5
    if word in ENABLE:
        return 0.3
    if word in LEAD:
        return 0.15
    if word in SAVE:
        return 0.22
    if word == "useful":
        return 0.85
    if word in {"fit", "fits", "fitting"}:
        return 0.13
    if word in CHINESE:
        return 0.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if any(ord(char) > 127 and char.isalpha() for char in token):
        candidates = [token.strip(" \t\n，。！；：、")]
        word = ""
    else:
        word = ""
        if carry is not None and carry[0] == doc and token[:1].isalpha():
            word = carry[1]
        finished = []
        for char in token:
            if char.isalpha():
                word = (word + char.lower())[-40:]
            elif word:
                finished.append(word)
                word = ""
        candidates = finished + ([word] if word else [])
    return (doc, word), max((score(w) for w in candidates), default=0.0)

