    'hinge': -0.6, 'hinges': -0.3,
    'boundary': -0.2, 'boundaries': -0.2,
    'marg': -0.8, 'argin': -1.5, 'borderline': -0.55,
    'extents': -0.5, 'ridge': -0.5, 'outskirts': -0.7,
    'interior': -0.3, 'portion': -0.27, 'portions': -0.2,
    'fringe': -0.5, 'integrity': -0.6,
}
# A few translations of the same origin/boundary concepts.
TRANSLATIONS = {
    '缘': -2.9, '緣': -2.9, '起源': -2.8,
    '原': -0.35, '源': -0.35, '边缘': -1.8, '边际': -1.0,
    '沿': -1.2, '边界': -0.6, '境界': -0.6, '海岸': -0.55,
    '出身': -0.45, 'границ': -1.2, 'область': -0.5,
    'región': -0.5,
}
OF_AFTER = {
    'origin': -1.7, 'origins': -1.2,
    'margin': -1.3, 'margins': -1.0,
    'edge': -0.6, 'edges': -0.3,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('_.-(').lower()
    value = ORIGINS.get(word, SPATIAL_LIMITS.get(word, 0.0))
    if word == 'of':
        value = OF_AFTER.get(previous, 0.0)
    value = TRANSLATIONS.get(word, value)
    if word == 'margin' and not token.startswith(' '):
        value = -3.6
    if word in ('edge', 'border') and not token.startswith(' '):
        value *= 0.65
    if word == 'origin':
        if token.startswith(('_', '.')):
            value = -3.6
        elif token.startswith('('):
            value = -2.9
        elif token.startswith('-'):
            value = -5.2
