programs.haiku:
"""Layer-0 MLP unit 1831 (down_proj) is a word detector for "origin / margin / edge /
border" words. Its activation is strongly NEGATIVE on those words and on a few near
synonyms (region, corner, extent, coast), and near zero everywhere else. The one
context effect: the word "of" right after "origin" is also negative.

The program reads the newest token (lower-cased, stripped) and the one before it, and
returns the typical activation for that word group, with the values taken from the
training rows.
"""

READS = ()

ORIGIN = {"origin", "-origin", "_origin", ".origin", "(origin", "起源"}
ORIGIN_MORE = {"origins", "originate", "originates", "originated", "originating", "origen"}
MARGIN = {"margin"}
MARGIN_MORE = {"margins", "argin", "marg"}
EDGE = {"border", "edge", "_edge", "-border"}
EDGE_MORE = {"borders", "edges", "緣", "缘"}
PLACE = {"region", "regions", "corner", "extent", "coast", "valley", "heritage"}


def group_value(word):
    if word in ORIGIN:
        return -4.0
    if word in ORIGIN_MORE:
        return -2.5
    if word in MARGIN:
        return -3.7
    if word in MARGIN_MORE:
        return -2.0
    if word in EDGE:
        return -1.4
    if word in EDGE_MORE:
        return -1.0
    if word in PLACE:
        return -0.7
    return 0.0


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    value = group_value(word)
    if word == "of" and len(prefix.token_strings) > 1:
        before = prefix.token_strings[-2].strip().lower()
        if before in ORIGIN or before in ORIGIN_MORE:
            value = -1.6
    return None, value

programs.sol:
"""A sparse spelling-based approximation of an abundance/enhancement signal.

English richness and improvement families, and several Chinese equivalents,
give negative values. Names sharing those spellings also match. Split English
words are joined; Japanese 豊 is recognized when its bytes finish a character.
Selected following prepositions continue the negative response. A few fixed
phrases ("very much", "right now", "New York") have positive responses.
Other words are mostly silent: weak unrelated lexical effects are not modeled.
"""
import re

READS = ()

ABUNDANCE = {'abundant', 'abundance', 'abund', 'undance', 'abundantly'}
ADVANCE = {'advance', 'advances', 'advanced', 'enriched'}
ENHANCEMENT = {
    'enhance', 'enhanced', 'enhances', 'enhancement', 'enhancements',
    'enrich', 'enrichment', 'advancement', 'advancing', 'robust',
    'refined', 'refinement', 'wealth', 'richness', 'robustness',
}
REFINING = {'enhancing', 'refining', 'refine', 'elaborate'}
RICHNESS = {
    'rich', 'richer', 'richest', 'wealthy', 'ample', 'extensive',
    'prosperity', 'prosperous', 'boom', 'advantageous', 'generous',
}
IMPROVEMENT = {'improvement', 'improvements', 'availability', 'advantage',
               'advantages', 'improve', 'improved', 'improving', 'expand',
               'expanded', 'expansion', 'enlarged', 'optimized', 'sophisticated',
               'vast', 'vigorous', 'excellence', 'innovations', 'bonus'}


def lexical(raw):
    word = raw.strip().strip('-').lower()
    if word == 'advancements':
        return -1.95
    if word in ABUNDANCE:
        return -1.8
    if raw.strip() in {'Advanced', 'Enhanced'}:
        return -1.0 if word == 'advanced' else -0.85
    if word in ADVANCE:
        return -1.4
    if word in ENHANCEMENT:
        return -1.1
    if word in REFINING:
        return -0.85
    if word in RICHNESS:
        return -0.65 if raw != 'rich' else -0.36
    if word in {'improvement', 'improvements', 'profound'}:
        return -0.55
    if word in {'availability', 'advantage', 'advantages'}:
        return -0.3
    if word == 'expansion':
        return -0.15
    if word in IMPROVEMENT:
        return -0.35
    # Fragment case matters: Ab starts 'abundance', AB is usually a label.
    if raw.strip('- ') == 'Ab':
        return -0.5
    if word in {'adv', 'enh'}:
        return -0.65
    if raw.strip() == 'Rob':
        return -0.75
    if word == 'rob':
        return -0.3
    if word in {'丰', '豐'}:
        return -5.3
    if word in {'丰富', '豐富', '完善'}:
        return -3.5
    if '丰富' in word or '完善' in word or word == '健全':
        return -2.5
    if (word in {'丰满', '充实', '完备', '繁荣', '饱满', '深厚'}
            or '健全' in word):
        return -1.6
    if word in {'隆', '盛', '旺', '富', '健', '善', '昌', '富裕', '详', '詳',
                '先进的', '发达', '深化', '壮大'}:
        return -1.0
    if word in {'先进', '先進', '优化', '改善', '改进', '强大的',
                '增强', '增強', '加强', '加強', '增进', '扩建', '裕',
                '繁', '兴', '興', '厚', '壮', '增', '増'}:
        return -0.5
    if word == 'бог':  # Russian stem of 'rich'; also occurs in names.
        return -0.65
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, tail = ('', '') if carry is None or carry[0] != doc else carry[1:]
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    value = lexical(raw)
    # Continue the spelling of an English word split across several tokens.
    joined = tail + raw if raw[:1].isascii() and raw[:1].isalpha() else raw
    joined_value = lexical(joined) if joined != raw else 0.0
    if joined_value:
        value = joined_value
    match = re.search(r'[A-Za-z]+$', joined)
    tail = match[0][-64:] if match else ''
    # Japanese 豊 (abundance) is split into byte tokens. Only score completion.
    if '\ufffd' in raw and prefix.text_prefixes[-1].endswith('豊'):
        value = -3.4

    if word == 'of':
        if previous == 'wealth':
            value = -1.4
        elif previous in {'abundance', 'advance', 'advancement', 'richness',
                          'prosperity'}:
            value = -1.0
        elif previous in {'enhancement', 'improvement', 'improvements', 'depth'}:
            value = -0.5
        elif previous in {'advantage', 'advantages', 'availability', 'expansion'}:
            value = -0.35
    if word == 'in':
        if previous in {'rich', 'advances', 'advancements'}:
            value = -1.05
        elif previous in {'abundant', 'advance', 'improvement', 'improvements'}:
            value = -0.3
    if word == 'on' and previous in {'elaborate', 'expand'}:
        value = -0.9
    if word == 'much':
        value = {'very': 1.0, 'pretty': 0.85, 'too': 0.28}.get(previous, 0.05)
    if word == 'now':
        value = 0.85 if previous == 'right' else 0.05
    if word == 'there' and previous == 'out':
        value = 0.33
    if word in {'york', 'yorkers', 'mexico'} and previous == 'new':
        value = 0.37
    if word == 'as' and previous == 'well':
        value = -0.14
    return (doc, word, tail), value

programs.haiku:
"""Layer-0 MLP down-projection component 1832: a "abundance and advancement" detector.

The component is negative on words for abundance and completeness (Chinese 丰, 丰富, 丰厚,
完善, 健全, 富裕, 充实, 盛; English abundant, abundance, rich, wealthy, plentiful, ample),
and on words for advancing or enhancing something (advance, advanced, enhance, refine,
improve). Most of the signal is on the one word itself, so the program looks each word up
and gives it its typical value; the scale is in nats-like activation units, most negative
for the Chinese words for abundance. It is also negative on "of" right after "wealth",
"abundance" or "prosperity" ("a wealth of"). It is weakly positive on "very much", "right now"
and "New York". Everything else is about 0.
"""

READS = ()

# Chinese single characters must match the whole token.
ZH_CHARS = {"丰": -5.0, "豐": -5.0, "富": -1.1, "盛": -1.8, "旺": -1.0, "隆": -1.3}
# Chinese words, matched inside the token.
ZH_WORDS = {
    "完善": -3.6, "丰富": -3.6, "豐富": -3.6, "健全": -2.5, "丰厚": -2.7, "深厚": -2.1,
    "充实": -1.9, "完备": -1.6, "丰满": -1.6, "旺盛": -1.4, "繁荣": -1.4, "兴旺": -1.4,
    "富裕": -1.4, "富有": -0.8, "富足": -1.1, "充裕": -0.9, "充足": -0.7, "高尚": -1.0,
    "深化": -1.2, "先进": -1.1, "优化": -0.7, "改进": -0.6, "加强": -0.5, "提升": -0.3,
}
# English words, matched by their beginning, so "Commonwealth" is not "wealth".
EN_STEMS = {
    "abund": -2.0, "advanc": -1.5, "enhanc": -1.3, "enrich": -1.1, "robust": -1.1,
    "wealth": -0.9, "prosper": -0.7, "refine": -1.0, "rich": -0.9, "improv": -0.5,
    "expan": -0.3, "elaborate": -0.8, "generous": -0.5, "extensive": -0.6, "vast": -0.35,
    "boom": -0.6, "ample": -0.7, "plentiful": -0.9, "affluent": -0.8, "advantag": -0.3,
}


def word_value(word):
    for stem, v in EN_STEMS.items():
        if word.startswith(stem):
            return v
    return 0.0


def token_value(token):
    s = token.strip()
    if s in ZH_CHARS:
        return ZH_CHARS[s]
    for word, v in ZH_WORDS.items():
        if word in s:
            return v
    return 0.0


def word_ending(strings):
    """The English word that the last token completes, from its earlier pieces too."""
    pieces = [strings[-1]]
    if pieces[0][:1] != " ":
        for s in reversed(strings[-5:-1]):
            if s[:1] == " " or not s.strip().isalpha():
                break
            pieces.insert(0, s)
    return "".join(pieces).strip().lower()


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    token = strings[-1].strip().lower()
    t = prefix.position
    same_doc = t > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = strings[-2].strip().lower() if same_doc else ""
    value = token_value(strings[-1])
    if value == 0.0:
        # an English stem counts only at the piece that completes it
        now = word_value(word_ending(strings))
        before = word_value(word_ending(strings[:-1])) if t > 0 else 0.0
        if now and not before:
            value = now
    if value == 0.0 and token == "of" and prev in ("wealth", "abundance", "prosperity"):
        value = -1.5
    if token == "much" and prev == "very":
        value = 1.1
    if token == "now" and prev == "right":
        value = 1.0
    if token == "york" and prev == "new":
        value = 0.4
    return carry, float(value)

programs.sol:
"""A naming-word detector, with weaker responses to other metadata labels.

The largest responses mark 'name', its grammatical forms, and name fields
in code. Chinese naming characters and several translations count too.
A JSON name key is especially strong; the word 'of' following name(s)
also responds. Affixes, case, and the preceding token adjust the prediction.
Only the current and immediately preceding token in the same document are
read; most other text is assigned zero.
"""
import re

READS = ()

# Small responses to words that label or locate a record's attributes.
METADATA = {
    'title': 1.55, 'titles': 1.15,
    'identifier': 1.0, 'identifiers': 1.0,
    'index': 1.1, 'indices': 0.64,
    'label': 0.65, 'labels': 0.55,
    'type': 0.65, 'types': 0.20,
    'date': 0.55, 'dates': 0.50,
    'count': 0.65,
    'text': 0.20, 'path': 0.65,
    'address': 0.55, 'addresses': 0.40,
    'description': 0.45, 'class': 0.40,
    'key': 0.60, 'url': 0.85, 'href': 0.65,
    'code': 0.28, 'signature': 0.80,
    'tag': 0.65, 'tags': 0.65, 'email': 0.40,
    'alias': 1.1, 'addr': 0.75, 'paths': 0.55,
}
TRANSLATIONS = {
    'nom': 1.1, 'nome': 2.6, 'nombre': 2.0,
    'nombres': 1.5, 'namen': 2.3,
    'имя': 3.7, 'имени': 2.6, 'название': 2.7,
    '명': 2.3, '이름': 4.7, 'nama': 2.9, 'naam': 2.6,
    'اسم': 2.6, 'tên': 2.9,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = ''
    if (len(prefix.token_strings) > 1
            and prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2]
    text = token.strip()
    word = text.strip('._-(/[{>\'"`:$\\').lower()
    before = previous.strip().strip('._(').lower()
    value = 0.0

    if word == 'name':
        value = 5.2
        if token == 'name':
            value = 7.05 if re.search(r'\{\s*["\']$', previous) else 5.9
            if before == 'operator':
                value = 1.8  # The tail of LaTeX's operatorname command.
            elif previous.endswith('__'):
                value = 6.7  # Python's special __name__ field.
        elif text == 'NAME':
            value = 5.7 if token[:1].isspace() else 5.3
        elif text.startswith('_'):
            value = 5.2 if text[1:] == 'Name' else 4.6
        elif text.startswith('('):
            value = 4.7
        elif text.startswith('['):
            value = 4.0
        elif text == '.Name':
            value = 5.5
        elif text.startswith(("'", '"')):
            value = 5.9
        if token[:1].isspace() and text == 'name':
            if before in ('given', 'real', 'common', 'short'):
                value = 6.2
            elif before in ('first', 'last', 'family', 'stage', 'user',
                           'file', 'field'):
                value = 4.0
            elif before == 'domain':
                value = 3.0
            elif before == 'param':
                value = 3.8
        elif text == 'Name' and before in ('type', 'domain', 'field'):
            value = 3.2
        if not previous:
            value = 4.5
    elif word == 'names':
        value = 4.7 if token[:1].isspace() else 4.0
    elif word in ('named', 'naming', 'rename', 'renamed'):
        value = 2.9
        if word in ('named', 'naming') and token[:1].isspace():
            value = 3.3 if word == 'named' else 3.8
    elif word == 'namely':
        value = 1.4
    elif word == 'namespace':
        value = 1.05
    elif word in ('getname', 'setname'):
        value = 4.4 if text.startswith('.') else 5.1
    elif word.endswith(('name', 'names')):
        # A name inside a compound identifier is weaker than 'name' alone.
        value = 2.7
        if word in ('filename', 'filenames',
                    'firstname', 'lastname', 'surname', 'dirname', 'basename'):
            value = 2.0
        elif word in ('username', 'usernames', 'hostname'):
            value = 1.45
        elif word == 'typename' and text.islower():
            value = 1.45
        elif word == 'pathname':
            value = 0.95
    elif '名' in text:
        if text in ('名', '名叫'):
            value = 5.2
        elif text.endswith('名字'):
            value = 4.7
        elif text in ('名称', '姓名', '命名', '名为'):
            value = 3.7
        elif re.fullmatch('[一二两三四五六七八九十百千万几]+名', text):
            value = 3.8
        else:
            value = 1.9
    elif word in ('nam', 'ame', 'ames', 'amed', 'aming', 'itle', 'itled'):
        # Letter fragments of name/named/names and title/titled.
        value = {'nam': 1.7, 'ames': 1.4}.get(word, 0.7)
    elif word in ('famous', 'renowned'):
        value = 1.0
    elif word in ('unnamed', 'nicknamed', 'nomenclature'):
        value = 2.7
    elif word in TRANSLATIONS:
        value = TRANSLATIONS[word]
        if word == 'nom' and text[:1].isupper():
            value = 2.0
    elif word == 'id':
        value = 1.1
        if text == 'id' and not token[:1].isspace():
            value = 1.1 if not previous[-1:].isalpha() else 0.10
        elif text == 'ID' and previous[-1:].isalpha():
            value = 0.7
    elif word in METADATA:
        value = METADATA[word]
        if word in ('type', 'class', 'key', 'description'):
            value += -0.1 if token[:1].isspace() else 0.2
        elif word == 'title' and token[:1].isspace() and text.islower():
            value = 1.35
    elif re.fullmatch(r'(get|set|.*by)id', word):
        value = 1.3
    elif re.search(r'[a-z](?:Id|ID)$', text):
        value = 1.05
    elif token == ' of' and before in ('name', 'names'):
        value = 1.5
    elif word in ('called', 'titled'):
        value = 0.4 if word == 'called' else 1.1
    return None, float(value)

programs.haiku:
"""Name detector for layer-0 MLP feature down_proj:1833.

The feature reads the current token and fires when it is the word "name" (or a close
relative), so it carries "this is a name / naming slot" into the residual stream.
Strongest on the bare word "name", most of all as a JSON or dict key (`{"name": ...`).
Medium on compounds ending in "name" (username, filename, _name) and on the word
"named"/"rename"; strong-ish on the Chinese word 名 ("name") and 名称 / 姓名.
Weak (about 1) on related identifier words (title, index, id, alias) and very weak
(about 0.7) on type, path, url, key, label. Everything else is 0.
"""

READS = ()

NAME_WORDS = {"name", "names"}
NAME_SUFFIX_WORDS = {"named", "rename"}
CJK_NAME = {"名", "名称", "姓名", "名为", "名字"}
WEAK_WORDS = {"title", "index", "id", "alias", "namespace", "nam", "namely", "nom", "nombre", "nome"}
FIELD_WORDS = {"type", "path", "url", "key", "label", "addr", "tag", "identifier", "slug"}
KEY_OPENERS = {'{"', '"', "'"}


def _word(s):
    return s.strip().strip("_.-\"'([{\t").lower()


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    w = _word(s)
    if w in NAME_WORDS:
        prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
        value = 7.0 if prev in KEY_OPENERS else 5.5
    elif s.strip() in CJK_NAME:
        value = 4.5
    elif w.endswith("name") or w in NAME_SUFFIX_WORDS:
        value = 3.0
    elif w in WEAK_WORDS:
        value = 1.2
    elif w in FIELD_WORDS:
        value = 0.7
    else:
        value = 0.0
    return carry, value

programs.luna:
"""Recognize name words and record-field labels in ordinary words or identifiers."""

READS = ()

FIELD_WORDS = (
    "date", "title", "id", "index", "type", "label", "count",
    "path", "namespace", "numberof",
)


def is_field_label(token, word):
    start = token.find(word)
    while start >= 0:
        end = start + len(word)
        before = token[start - 1] if start else ""
        after = token[end] if end < len(token) else ""
        if not before.isalpha() and not after.isalpha():
            return True
        start = token.find(word, start + 1)
    return False


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lower()
    if "name" in token:
        return None, 5.0
    if any(is_field_label(token, word) for word in FIELD_WORDS):
        return None, 1.0
    return None, 0.0

programs.sol:
"""Spheres, planets, and related physical vocabulary give negative activations.

Use graded lexical classes: spherical things are strongest, then Earth and
atmosphere, then geometry, global scope, and matter. Include common word
fragments and a few Chinese equivalents. On 'of', retain a weaker response
to the preceding physical noun. Two small positive classes cover quantity
phrases and statements ending in 'that'. Unrelated tokens stay near zero.
"""

READS = ()

SPHERES = {'sphere', 'hemisphere'}
EARTH = {'earth', 'globe'}
ATMOSPHERE = {'atmosphere', 'atmospheric', 'planetary'}
GLOBAL = {'global', 'worldwide'}
ELEMENTS = {'oxygen', 'nitrogen', 'mercury', 'xygen'}
MATTER = {'atom', 'atoms', 'sulfur', 'sulph', 'phosph', 'osph', 'magnet'}
WORLD_AND_SPACE = {
    'ocean', 'oceans', 'orbit', 'meteor', 'terrestrial', 'restrial',
    'continent', 'continents', 'venus', 'neptune', 'lunar', 'atlas',
    'earthly',
}
SOLID_GEOMETRY = {'cube', 'vertex'}
ROUND_AND_ORBITAL = {
    'circle', 'cylinder', 'cylindrical', 'dome', 'pyramid', 'satellite',
    'satellites', 'asteroid', 'asteroids', 'polar', 'arctic', 'cone',
    'moon', 'moons', 'balls', 'vertices', 'sph', 'orb', 'astro', 'geo',
    'orbital', 'astronaut', 'pluto',
}
MATERIALS_AND_FRAGMENTS = {
    'carb', 'arbon', 'sulf', 'methane', 'charcoal', 'graphite',
    'helium', 'manganese', 'ozone', 'agnet',
}
SMALL_MATTER = {
    'particle', 'particles', 'electrons', 'proton', 'neutron', 'photons',
    'hydrogen', 'molecule', 'molecules', 'beads', 'carbonate', 'sulfate',
    'methyl',
}
CURVES_AND_MEASURES = {'radius', 'diameter', 'arc', 'arcs', 'disk', 'circles'}
SKY_AND_SCIENCE_FRAGMENTS = {
    'solar', 'galaxy', 'galactic', 'universe', 'aerial', 'airborne',
    'jet', 'phot', 'hem', 'canopy',
}
QUANTITIES = {
    'amount', 'total', 'loss', 'effect', 'effects', 'rate', 'impact',
    'weight', 'power', 'benefits', 'advantage',
}
GOALS_AND_COSTS = {'cost', 'gain', 'goal', 'aim', 'benefit', 'expense'}


def clean(token):
    return token.strip().strip('._-/()[]{}:,;"\'').lower()


def lexical_value(token, previous=''):
    word = clean(token)
    # Chinese names for Earth, balls, planets, and the globe.
    if word == '地球':
        return -5.7
    if word in {'星球', '地球上'}:
        return -4.0
    if word == '球':
        # Baseball/balloon compounds weaken the bare sphere response.
        return -1.8 if previous in {'棒', '野', '气'} else -4.1
    if word == '环球':
        return -3.5
    if word in {'全球', '行星', '碳'}:
        return -2.55
    if word in {'眼球', '火星', '珠', '在全球'}:
        return -1.95
    if word == '大气':
        return -1.6
    if word in {'氧', '炭', '弧', '海洋', '全世界'}:
        return -1.2
    if word in {'太阳', '圆', '圓', '磁', '空气', '宙'}:
        return -0.8
    if word in {'気', '氣', '气', '环', '環', '円', '足球', '宇', '天空', '星'}:
        return -0.5
    if word in {'сфере', 'круг', 'миров', 'matière', 'โลก'}:
        return -1.0
    if word in SPHERES or word == 'pherical':
        return -4.4
    if word in {'spherical', 'planet'}:
        whole_lowercase = token.startswith(' ') and token.lstrip()[0].islower()
        return -3.7 if whole_lowercase else -3.0
    if word in {'spheres', 'planets'}:
        return -3.25
    if word in {'phere', 'pheres', 'osphere', 'pheric'}:
        if previous.endswith(('mos', 'atmos', 'atos')):
            return -1.75 if word == 'pheric' else -2.3
        return -3.0
    if word == 'etary':
        return -2.1 if previous.endswith('plan') else 0.002
    if word == 'cury':
        return -1.8 if previous.endswith('mer') else 0.002
    if word in EARTH:
        return -2.95
    if word in ATMOSPHERE:
        return -2.4
    if word in {'carbon', 'atmos', 'glob'}:
        return -1.8
    if word in GLOBAL or word in ELEMENTS or word in {'jupiter', 'upiter'}:
        return -1.35
    if word in MATTER or word in WORLD_AND_SPACE or word in SOLID_GEOMETRY:
        value = -1.05
        if word in {'cube', 'atom', 'atoms'} and not token.startswith(' '):
            value *= 0.65
        return value
    if word == 'ball':
        return -1.2 if token.startswith(' b') else -0.8
    if word in {'electron', 'photon', 'oglob', 'globally', 'globals'}:
        return -0.9
    if word == 'saturn':
        return -2.25
    if word == 'mars':
        return -0.8 if token.strip().startswith('M') else 0.0
    if word in ROUND_AND_ORBITAL or word in MATERIALS_AND_FRAGMENTS:
        return -0.72
    if (word in SMALL_MATTER or word in CURVES_AND_MEASURES
            or word in SKY_AND_SCIENCE_FRAGMENTS):
        return -0.45
    if word in {
        'air', 'gas', 'star', 'stars', 'cubic', 'magnetic', 'eye',
        'climate', 'environment', 'environmental', 'soil', 'tube', 'bowl',
        'acid', 'oxide', 'amino', 'hydro',
    }:
        return -0.27 if token.startswith(' ') else 0.0
    return 0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, strength = ('', 0.0)
    if carry is not None and carry[0] == doc:
        previous, strength = carry[1:]
    token = prefix.token_strings[-1]
    word = clean(token)
    lexical = lexical_value(token, previous)
    value = lexical
    if token == ' of':
        if strength < -0.3:
            value = 0.36 * strength
        elif previous in GOALS_AND_COSTS:
            value = 0.32
        elif previous in QUANTITIES:
            value = 0.15
    elif token == ' that' and previous in {
        'such', 'mean', 'means', 'note', 'notice',
    }:
        value = 0.21
    return (doc, word, lexical), float(value)

programs.haiku:
"""Layer-0 MLP down_proj component 1835: a weak word-class guess that explains almost nothing.

What it does: looks only at the token at the current position and gives a small
signed value for a few word classes:
  - possessive pronouns (你的, 我的, 它的 ...) and bare 你/我/他: -0.15
  - demonstratives (这, 这一, 这些 ...) and quantifier/adverb words (都, 也, 大家, 虽然 ...): +0.1
  - Japanese case/topic particles (を, は, に, が, で, と, の): -0.05
Everything else predicts 0.

Why it is this weak: the component is almost never active (CI > 0.1 at 9 of 10M
tokens), and its activation is diffuse. Its word-class means have mixed signs and
small magnitudes; the Japanese particle mean (-0.04 over ~1300 tokens) is the only
consistent one. A per-token lookup needs about 1000 tokens to reach 10% held-out
variance and about 23k tokens to reach 27%, so no short list of words captures it.
"""

READS = ()

POSSESSIVE_PRONOUNS = {"你的", "我的", "他的", "她的", "它的", "我们的", "你们的", "他们的", "它们的"}
BARE_PRONOUNS = {"你", "我", "他"}
DEMONSTRATIVES = {"这", "这一", "这些", "这个", "这种", "这样", "那", "那些"}
QUANTIFIERS = {"都", "也", "大家", "虽然", "还要", "很多", "有些", "已经"}
JAPANESE_PARTICLES = {"を", "は", "に", "が", "で", "と", "の"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if word in POSSESSIVE_PRONOUNS or word in BARE_PRONOUNS:
        value = -0.15
    elif word in DEMONSTRATIVES or word in QUANTIFIERS:
        value = 0.1
    elif word in JAPANESE_PARTICLES:
        value = -0.05
    else:
        value = 0.0
    return carry, value

