"""A negative detector for short written forms of the consonant /k/.

Single letters dominate, especially Cyrillic ka, Greek kappa and Arabic
kaf. Script, case, and a leading space change their strength. Common Asian
k-syllables also respond. Longer fragments dilute the signal sharply.
For byte-split tokens, the last decoded character supplies the response
when complete; selected k-character completions receive extra strength.
This intentionally leaves unrelated, smaller lexical effects at zero.
"""

READS = ()

# K-series syllables, consonants, and common Chinese k-initial characters.
K_FORMS = {
    'ク': 1.59, 'ケ': 1.13, 'カ': 0.93, 'キ': 0.46, 'コ': 0.69,
    'く': 0.92, 'か': 0.16, 'き': 0.16,
    'ก': 1.77, 'ค': 2.34,
    'क': 2.90, 'ক': 3.10, 'க': 1.44, 'క': 2.10,
    '크': 1.35, '코': 1.05, '커': 0.95, '클': 1.00,
    '케': 0.71, '카': 0.28, 'ㅋ': 0.84,
    '克': 2.60, '肯': 0.87, '柯': 0.77, '科': 0.39,
    '可': 0.30, '凯': 0.49, '凱': 0.49, '库': 0.37, '庫': 0.37,
}


def response(token):
    word = token.strip()
    if not word:
        return 0.0
    initial = token[:1].isspace()
    lower = word.lower()
    if lower == 'к':
        if word == 'К':
            return -2.99 if initial else -2.77
        return -3.44 if initial else -2.11
    if lower == 'κ':
        return -1.91 if initial else -1.60
    if word == 'ك':
        return -3.47 if initial else -2.10
    if word == 'ک':
        return -2.74 if initial else -1.93
    if lower == 'как':  # Russian "how/as": two k sounds.
        return -1.50 if word.islower() else (-1.27 if initial else -1.95)
    if 'к' in lower:
        return -4.0 * lower.count('к') / len(word) ** 2.5
    if 'κ' in lower:
        return -1.6 * lower.count('κ') / len(word) ** 2.5
    if 'ك' in word or 'ک' in word:
        # The Arabic definite article does not dilute a following lone kaf.
        if word in ('الك', 'الک'):
            return -2.4
        return -3.5 * (word.count('ك') + word.count('ک')) / len(word) ** 2.5
    if word in K_FORMS:
        return -K_FORMS[word]
    strength = sum(K_FORMS.get(c, 0.0) for c in word)
    if strength:
        # Small tsu marks gemination, rather than a separate full syllable.
        size = max(1, len(word.replace('ッ', '')))
        return -0.8 * strength / size ** 2.5
    if lower == 'k':
        return -0.35 if initial else (-0.24 if word == 'K' else -0.09)
    if lower.startswith('ck'):
        return -0.85 / max(1, len(word) - 1) ** 1.3
    if lower in ('.k', '-k', ',k', '_k'):
        return -0.48
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = response(token)
    if '�' in token and prefix.position > 0:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            char = prefix.text_prefixes[-1][-1:]
            if char and char != '�':
                value = response(char)
                if char in 'Κクカ':
                    value *= 2.2 if char in 'Κク' else 2.0
                elif char in 'ケコКகక可':
                    value *= 1.4
    return None, float(value)

