programs.haiku:
"""Clause-opening subjects: this component fires on the first word of a new clause or
noun phrase that comes straight after a comma, as in "When X, it ..." or "In Y, the ...".
It is strongest when that word is a subject pronoun or 'the' (about 2), weaker for other
clause openers such as 'so', 'then', 'I', 'what' (about 1.4) and for a/an/all (about 0.9),
and slightly negative for prepositions that open a phrase after a comma ("..., with",
"..., as", "..., of"). After a semicolon, dash, or the words 'so'/'then' it is about a third
as strong. Everywhere else it is zero, and so is the end-of-document token's neighbour."""

READS = ()

SUBJECT = {"it", "there", "you", "they", "we", "he", "she", "the", "this", "these", "its", "his", "their"}
OPENER = {"i", "so", "then", "what", "how", "one", "our", "let", "those", "some", "her", "your", "my"}
QUANT = {"a", "an", "all", "both", "many", "each", "most", "two"}
PREP = {"with", "as", "of", "for", "from", "at", "in", "on", "or"}
COMMA_MARKS = (",", "，", "$,", '",', "),")
WEAK_MARKS = (";", "–", "—")
WEAK_WORDS = ("so", "then")


def step(carry, prefix, upstream):
    if prefix.token_strings[-1] == "<|endoftext|>":
        return carry, 0.75
    if len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    before = prefix.token_strings[-2].strip().lower()
    if before.endswith(COMMA_MARKS):
        strength = 1.0
    elif before in WEAK_MARKS or before in WEAK_WORDS:
        strength = 0.35
    else:
        return carry, 0.0
    word = prefix.token_strings[-1].strip().lower()
    if word in SUBJECT:
        value = 2.0
    elif word in OPENER:
        value = 1.4
    elif word in QUANT:
        value = 0.9
    elif word in PREP:
        value = -0.3
    else:
        value = 0.0
    return carry, strength * value

