"""A comma can introduce a new clause or phrase.

Predict larger positive contributions for a short list of common starters after commas;
predict zero elsewhere, except for the end-of-text marker. This is a lexical cue, not a
general grammar parser.
"""

READS = ()

STARTERS = {
    "it": 2.6, "they": 2.5, "this": 2.5, "the": 2.2,
    "its": 2.1, "we": 2.0, "he": 2.0, "i": 1.7,
    "then": 1.6, "so": 1.3, "let": 1.2, "il": 1.0,
