OTHER_DETERMINERS = {"an", "these", "those", "their", "my", "his", "her", "our"}
OTHER_CONNECTORS = {"and", "but", "because", "when", "while"}


def step(carry, prefix, upstream):
    t = prefix.position
    word = prefix.token_strings[t].strip().lower()
    if word == "<|endoftext|>":
        return None, 0.8
    if t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]:
