"""A lexical 'less' detector, not a general detector of smallness.

Separate-word LESS and attached -less fragments give large negative
signals. Related comparative and reduction words respond more weakly,
as do several translations. Spelling can override meaning: lesson fires.
'Or less' and 'at least' are weaker than unqualified less/least.
Amplitudes are rounded training estimates. Unlisted tokens are zero;
their small, token-specific fluctuations are not modeled.
"""
READS = ()

# Different lexical strengths of words meaning less/fewer/little.
LESS_WORDS = {
    'fewer': -2.7, 'moins': -2.75, 'menos': -2.3,
    'meno': -1.55, 'weniger': -4.5, 'wenig': -1.2,
    'менее': -2.1, 'меньше': -1.3,
}
REDUCTION_VERBS = {'reduce', 'reduces', 'reduced', 'reducing'}
REDUCTION_NOUNS = {'reduction', 'reductions'}
DECREASE_WORDS = {'decrease', 'decreases', 'decreased', 'decreasing'}
LESS_CHARACTERS = {'少', '減', '减', '减少', '減少'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    word = token.strip()
    lower = word.lower()
    value = LESS_WORDS.get(lower, 0.0)
    if lower.lstrip('_-') == 'less':
        if lower != 'less':
            value = -5.7
        elif word.isupper():
            value = -5.5
        elif token[:1].isspace():
            value = -5.95 if word == 'Less' else -6.25
            if previous.strip().lower() == 'or':
                value = -5.46
        elif word == 'Less':
            value = -7.6
        else:
            attached = previous and previous[-1].isalpha()
            value = -3.95 if attached else -6.25
    elif lower in {'lessly', 'lessness'}:
        value = -2.4
    elif lower in {'lesser', 'lesson', 'lessons'}:
        value = -2.1
    elif lower == 'least':
        value = -0.33 if previous.strip().lower() == 'at' else -1.35
    elif lower == 'les':
        value = -0.2 if token[:1].isspace() else -0.3
    elif lower in REDUCTION_VERBS:
        value = -0.9
    elif lower in REDUCTION_NOUNS:
        value = -0.4
    elif lower in DECREASE_WORDS:
        value = -0.28
    elif word in LESS_CHARACTERS:
        value = -1.4
    elif lower in {'smaller', 'greater'}:
        value = -0.6
    elif lower in {'slower', 'sooner'}:
        value = -0.73
    elif lower in {'shorter', 'weaker', 'easier', 'narrower'}:
        value = -0.34
    elif word in {'≤', '<='}:
        value = -0.33
    return (doc, token), float(value)

programs.haiku:
"""Layer-0 MLP component down_proj:1842: a "less / fewer" detector.

The component writes into the residual stream a strongly negative signal when the
current token is the comparative word "less" (" less", "Less"), and a weaker one
on other words meaning fewer / a smaller amount (fewer, lesser, moins, weniger,
meno, 少) and on the reduce / smaller / greater family. Everywhere else it is
close to zero.

A "less" glued onto the end of another word (lifeless, painless, wordless) is
weaker than the free word " less". Predictions are the typical activation for
each word, in the units the component really has.
"""

READS = ()

# Free-standing comparative "less": "less likely", "no less than", "or less".
FREE_LESS = {" less", " Less"}
# "less" glued to a stem: "lifeless", "smokeless", "wordless".
GLUED_LESS = {"less", "Less"}
# Other words for fewer / a lesser amount, incl. the word "lesson" and foreign words.
FEWER = {
    " fewer": -2.7, " lesser": -2.2, " lesson": -2.3, " lessons": -2.3,
    " moins": -2.9, " weniger": -4.3, " meno": -1.6, " менее": -2.1,
    "少": -1.6, "减少": -1.5,
}
# Reduce / smaller / greater family: weak.
WEAK = {
    " reduce": -0.9, " reduced": -0.95, " reduces": -0.85, " reducing": -0.8,
    " reduction": -0.35, " decrease": -0.2, " decreased": -0.4,
    " smaller": -0.66, " greater": -0.55, " least": -0.5, " shorter": -0.4,
}
TABLE = {**FEWER, **WEAK}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in FREE_LESS:
        return None, -6.2
    if token in GLUED_LESS:
        return None, -4.5
    return None, TABLE.get(token, 0.0)

programs.sol:
"""A junction between an a-ending word piece and a following vowel.

Repeated a is positive; a change to another vowel is negative. The same
spelling pattern is recognized in several scripts. Longer pieces, spaces,
and hiragana are weaker cues than short adjoining fragments.
An isolated a at the start of a document is also positive.
"""
import unicodedata

READS = ()
A_KANA = 'ぁあかがさざただなはばぱまゃやらゎわァアカガサザタダナハバパマャヤラヮワ'


def vowel(c, ending=False):
    if c.lower() == 'й':  # a consonantal glide, not a vowel
        return ''
    chars = unicodedata.normalize('NFKD', c.lower())
    if not chars:
        return ''
    x = chars[0]
    if x in 'aeiouy':
        return x
    # Hangul: an a-ending open syllable, or a vowel-initial syllable.
    if '\uac00' <= c <= '\ud7a3':
        jamo = unicodedata.normalize('NFD', c)
        if ending:
            return 'a' if len(jamo) == 2 and jamo[1] == 'ᅡ' else ''
        if jamo[0] == 'ᄋ':
            return {'ᅡ': 'a', 'ᅵ': 'i', 'ᅮ': 'u',
                    'ᅩ': 'o', 'ᅥ': 'o', 'ᅦ': 'e'}.get(jamo[1], '')
        return ''
    if ending and (x in A_KANA or x == 'я'):
        return 'a'
    # Vowel spellings in Cyrillic, Greek, Arabic and kana.
    for letters, sound in (
        ('аαاぁあァア', 'a'), ('иіыιيیぃいィイ', 'i'),
        ('уυぅうゥウ', 'u'), ('еэєεηぇえェエ', 'e'),
        ('оωοぉおォオ', 'o'), ('ю', 'u'), ('я', 'y'),
