    doc, text = prefix.document_ids[-1], prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    value = 0.0
    if first and text.strip() in ('a', 'A'):
        value = 1.38 if text.startswith(' ') else 2.0
    elif previous and vowel(previous[-1], ending=True) == 'a':
        fragment = text.lstrip(' ._\'\"')
        sound = vowel(fragment[:1])
        if sound:
            value = {'a': 2.3, 'i': -1.9, 'u': -1.5,
                     'e': -1.3, 'o': -0.8, 'y': -1.2}[sound]
            value *= min(1.0, 3 / max(1, len(previous.strip()))) ** 2
            value *= min(1.0, 3 / max(1, len(fragment)))
            c = fragment[0].lower()
            if c in 'иу':
                value *= 1.7
            if c == 'я':
                value *= 0.6
            if c in 'ює':
                value *= 0.25
            if c in 'ιυίὶ':
                value *= 1.4
            if c in 'íîï':
                value *= 1.4
            if previous[-1].lower() in 'äáàâ':
                value *= 0.5
