YEAR_WORDS = {
    'jahr': -1.4, 'jahres': -1.5, 'jahre': -2.5, 'jahren': -2.4,
    'année': -2.3, 'années': -2.3, 'año': -2.1, 'años': -2.0,
    'anos': -1.5, 'anni': -1.1, 'annum': -1.7,
    'год': -1.9, 'году': -1.85, 'года': -1.5, 'годы': -2.0, 'лет': -1.0,
    'jaar': -2.6, 'tahun': -2.4, 'năm': -2.1, 'år': -1.1,
    'عام': -1.8, 'العام': -0.7, 'سنة': -1.3, 'السنوات': -3.0,
    '연': -2.3, 'yıll': -4.2,
