YEAR_PARTS = set('年初 年末 年底 周年 新年 年限 年报 年終 过年'.split())
YOUTH = set('青年 童年 年轻 年輕 年轻人 年轻的 年纪 年代 年级 年夜'.split())
NUMERALS = set('一二三四五六七八九十两兩')


