    token = prefix.token_strings[-1]
    word = token.strip().strip('.,()[]{}:-_/').lower()
    prev = ''
    if prefix.position and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    value = 0.0
    if word == '年':
        value = -7.95 if prev.isdigit() else -8.55
    elif word == '년':
        value = -5.4
    elif word in SHORT_YEARS:
        value = -5.7
    elif word in {'每年', '近年', '逐年', '百年', '千年'}:
        value = -5.1
    elif word in {'去年', '全年'}:
        value = -4.6
    elif word.endswith('年') and all(c in NUMERALS for c in word[:-1]):
        value = -6.0 if len(word) == 2 else -4.7
    elif word.endswith('半年'):
        value = -3.5
    elif word in YEAR_PARTS:
        value = -2.6
    elif word in YOUTH:
        value = -1.1
    elif word == '少年':
        value = -2.0
    elif '年' in word:
        if any(s in word for s in ('成年', '嘉年', '青少年')):
            value = -0.3
        elif '龄' in word or '齡' in word or word == '老年人':
            value = -0.6
        else:
            value = -3.5 if len(word) < 4 else -2.6
    elif word in {'year', 'years'}:
        value = -3.4
        if token.startswith('-') and word == 'year':
            value = -4.1
        elif token.startswith('.'):
            value = -4.5
    elif word == 'annual':
        value = -4.0 if token == ' annual' else -3.2
    elif word in {'annually', 'yearly'}:
        value = -2.5
    elif word in YEAR_WORDS:
        value = YEAR_WORDS[word]
        if not token[:1].isspace():
            if word in {'год', 'лет', 'anni', 'anos', 'år'}:
                value *= 0.25
            elif word == 'année':
                value = -1.4
    elif word.startswith('jähr'):
        value = -1.7
    elif word in {'month', 'months', 'monthly', '月', '月份'}:
        value = -0.3 if word == 'month' else -0.7
        if word == '月' or token.startswith('-'):
            value = -1.1
    elif word in {'decade', 'decades'}:
        value = -1.85
    elif word in {'century', 'semester', 'lifetime', 'anniversary'}:
        value = -0.65
    elif word == 'centuries':
        value = -1.4
    elif word in {'岁', '歲', '歳', '岁的'}:
        value = -1.3
    elif word in {'of', 'old', 'ago'} and prev.strip('-()._/') in {'year', 'years'}:
        value = {'of': -1.2, 'old': -0.75, 'ago': -0.5}[word]
    elif token == '-old':
        value = -0.9
