    "year", "years", "year's", "years'", "annual", "annually",
    "année", "années", "anni", "anno", "anos", "ano", "año", "años",
    "jahre", "jahren", "jahr", "год", "года", "году", "лет",
    "година", "години", "годину", "годів", "років", "року",
    "yıl", "yıllık", "yillik", "jaar", "jaren", "år", "året",
    "godi", "godine", "godina", "godinu", "godinama",
    "سنوات", "سنة", "السنوات",
