    word = prefix.token_strings[-1].strip().lower()
    clean = word.strip(" \t\r\n.,;:!?()[]{}\"'“”‘’<>/\\_")

    # The character 年 marks a year in Chinese and Japanese text.
    if "年" in word:
        return None, -5.1 if "去年" in word else -7.8
    # Age and month words have a smaller version of the same time-period signal.
    if any(mark in word for mark in ("岁", "歲")):
        return None, -1.1
