        return None, 0.0

    if clean in {"année", "années", "anni", "anno", "anos", "ano", "año", "años"}:
        return None, -1.5
    if clean in {"год", "года", "году", "лет", "година", "години", "годину", "годів", "років", "року"}:
        return None, -1.8
    if clean in {"jahre", "jahren", "jahr", "jaar", "jaren", "år", "året"}:
        return None, -1.9
    if clean in {"سنوات", "سنة", "السنوات"}:
