READS = ()

TERMS = (
    "coin", "currenc", "denomin", "mint", "exchange", "fed",
    "paper", "print", "page", "book", "stamp", "ticket", "envelope",
    "label", "postal", "mail", "ribbon", "medal",
)
CJK_TERMS = set("票印邮郵编枚书書局面版")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ""
    lower = token.lower()

    if len(token) == 1 and token in CJK_TERMS:
        word = ""
        value = -0.05
    else:
        if any(ch.isspace() for ch in lower):
            word = lower.rsplit(None, 1)[-1] if lower[-1:].strip() else ""
        else:
            word = previous + lower
        if word and not word[-1].isalnum():
            word = ""
        if word.endswith("colorful"):
            value = 0.05
        elif any(term in word for term in TERMS):
            value = -0.05
        else:
            value = 0.0

    return (doc, word[-32:]), value

programs.sol:
"""Approximate a boundary-and-orthographic-fragment response.

Chat, tool and reasoning delimiters give the largest positive responses.
Their strength grows with document position; message endings immediately after
closed tool blocks are weaker. Short foreign-script pieces give smaller
responses, with script, word-start, case and grammatical-piece distinctions.
Most ASCII and Chinese content is zero. For split UTF-8 characters, inspect the
completed character, or use recent non-Latin script context. That context
expires after 32 tokens without a fully decoded non-Latin piece.

These are coarse training-fitted levels, not word-specific predictions.
"""
from functools import lru_cache
import unicodedata

READS = ()
CYRILLIC_VOWELS = frozenset('аеёиоуыэюя')
# (long-document level, early-position reduction, first-token level)
BOUNDARIES = {
    '<|im_end|>': (5.94, 2.32, 2.86),
    '<|im_start|>': (3.54, 1.23, 1.97),
    '<tool_call>': (5.14, 1.35, 2.50),
    '</tool_call>': (4.15, 1.51, 2.22),
    '<tool_response>': (2.95, 1.14, 1.51),
    '</tool_response>': (2.98, 0.64, 1.95),
    '<think>': (2.62, 1.13, 1.50),
    '</think>': (4.60, 1.81, 2.19),
}
RUSSIAN_FUNCTION_WORDS = frozenset('''
в и с к у о на по от до за из об не ни но да то же бы
для при над под без про как что это все мы вы он она они
его ее их или так чем который которые этой этого
'''.split())
RUSSIAN_ENDINGS = frozenset('''
ов ом ой ая ый ых ым ами ями ого ему ать ить еть
ка ки ку ко ок ик ую ые ий ный ная ные ной ных ным ает ают
'''.split())
JAPANESE_GRAMMATICAL_PIECES = frozenset('の を が は と も し て する して した'.split())
KOREAN_GRAMMATICAL_PIECES = frozenset('의 이 가 는 은 고 한 도 해'.split())


@lru_cache(maxsize=65536)
def piece_value(s):
    word = s.strip()
    letters = [c for c in word if c.isalpha() or
               unicodedata.category(c).startswith('M')]
    if not letters:
        return 0.0
    name = unicodedata.name(letters[0], '')
    n = len(letters)
    space = s.startswith(' ')
    if 'CYRILLIC' in name:
        if word == word.lower() and space and word in RUSSIAN_FUNCTION_WORDS:
            return -0.04
        if not space and word in RUSSIAN_ENDINGS:
            return -0.07
        if word[0].isupper():
            return ((0.52 if word.lower() in CYRILLIC_VOWELS else 0.76)
                    if n == 1 else 0.45 if n <= 3 else 0.15)
        if n == 1:
            if word in CYRILLIC_VOWELS:
                return 0.50 if space else 0.05
            return 0.72 if space else 0.30
        return ((0.33 if space else 0.14) if n <= 3 else
                0.15 if space and n == 4 else 0.0)
    if 'ARABIC' in name:
        if space and word in {'و', 'في', 'من', 'على'}:
            return 0.22
        if space and n == 1:
            return 0.77
        return 0.53 if n <= 3 else max(0.15, 0.70 - 0.07*n)
    if 'HANGUL' in name:
        if word in KOREAN_GRAMMATICAL_PIECES and not space:
            return 0.02
        if n == 1:
            return 1.18 if space else 0.47
        return 0.46 if space and n == 2 else 0.27
    if 'KATAKANA' in name:
        return max(0.20, 0.59 - 0.075*n)
    if 'HIRAGANA' in name:
        if word in JAPANESE_GRAMMATICAL_PIECES:
            return -0.08
        return 0.28 if n == 1 else 0.10 if n == 2 else 0.0
    if 'GREEK' in name:
        return 0.19 if space else 0.50
    if 'THAI' in name:
        return max(0.4, 0.88 - 0.035*n)
    if any(script in name for script in
           ('HEBREW', 'DEVANAGARI', 'BENGALI', 'GURMUKHI', 'TAMIL')):
        return 0.75
    accents = [c for c in letters if ord(c) > 127 and
               'LATIN' in unicodedata.name(c, '')]
    if accents:
        if any(ord(c) >= 256 for c in accents):
            return max(0.10, 0.49 - 0.065*n) + (0.15 if space and n == 1 else 0.0)
        return (0.11 if space else 0.06) if n <= 4 else 0.0
    return 0.0


@lru_cache(maxsize=65536)
def script_of(s):
    for c in s:
        name = unicodedata.name(c, '')
        for script in ('HIRAGANA', 'KATAKANA', 'HANGUL', 'CJK',
                       'CYRILLIC', 'ARABIC', 'GREEK', 'THAI', 'LATIN',
                       'HEBREW', 'DEVANAGARI', 'BENGALI', 'TAMIL'):
            if script in name:
                return script
    return ''


def broken_value(s, completed, recent_script):
    """A completed UTF-8 letter differs from an unfinished leading fragment."""
    if completed:
        if completed == 'CJK':
            return 0.36 if recent_script in ('HIRAGANA', 'KATAKANA') else 0.24
        if completed in ('HIRAGANA', 'KATAKANA', 'HANGUL'):
            return 0.58
        return 0.45
    if s.startswith(' '):
        if recent_script == 'HANGUL':
            return 1.25
        if recent_script in ('HIRAGANA', 'KATAKANA', 'CYRILLIC'):
            return 0.25
        return 0.04 if recent_script == 'CJK' else -0.10
    if recent_script in ('CJK', 'HIRAGANA', 'KATAKANA'):
        return -0.16
    return 0.20


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, recent_script, age = 0, '', 0
    else:
        _, position, recent_script, age = carry
    # Count within a document and keep a short-lived script context.
    if age >= 32:
        recent_script = ''
    if s in BOUNDARIES:
        mature, reduction, initial = BOUNDARIES[s]
        value = (initial if position == 0 else
                 mature - reduction/(1 + position)**0.5)
        if s == '<|im_end|>' and position:
            previous = prefix.token_strings[-2]
            if previous == '</tool_call>':
                value -= 1.16
            elif previous == '</tool_response>':
                value -= 1.03
    elif '\ufffd' in s:
        completed = script_of(prefix.text_prefixes[-1][-1:])
        value = broken_value(s, completed, recent_script)
    else:
        value = piece_value(s)
        script = script_of(s)
        if script and script != 'LATIN':
            # Han text can belong to a surrounding Japanese/Korean passage.
            if (script != 'CJK' or
                    recent_script not in ('HIRAGANA', 'KATAKANA', 'HANGUL')):
                recent_script = script
            age = 0
    return (doc, position + 1, recent_script, age + 1), float(value)

