MARKER_ACTIVATIONS = {
    "<|im_start|>": 3.4,
    "<tool_call>": 4.9,
    "</tool_call>": 4.1,
    "<tool_response>": 2.9,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == "<|im_end|>":
