"""Score spelling continuations after c, g, k and their script counterparts.

The largest signal is a following r, then l or another velar consonant.
A vowel followed by r/l also responds, as in -er or -al. Long fragments
and uppercase onsets weaken the response. This is a local spelling rule,
not a word list; unrelated contexts are approximated by zero.
"""
import math

READS = ()
VELARS = frozenset('cgkгкγκكکگ')
RHOTICS = frozenset('rрρر')
LATERALS = frozenset('lлλل')


def continuation(token):
    text = token.lower()
    first, second = text[0], text[1:2]
    length = len(token)
    short = math.exp(-0.28 * max(length - 2, 0))
    if first in RHOTICS:
        value = 1.9 * short
        if first != 'r':
            value *= 1.25
    elif first in LATERALS:
        value = 1.12 / math.sqrt(length)
    elif first in VELARS - {'c'}:
        value = 0.72 * math.exp(-0.23 * max(length - 3, 0))
    elif first in 'scсhхfфvвw':
        value = 0.3 / math.sqrt(max(length / 2, 1))
    elif first in 'dtдт':
        value = -0.16
    elif first in 'eеεaаαiиιoоοuуυ':
        value = 0.08 if length <= 2 else -0.08
        if second in RHOTICS:
            value += 0.85 * short
        elif second in LATERALS and first in 'aаαeеε':
            value += 0.8 * short
        elif second in LATERALS and first in 'oоο':
            value += 0.4 * short
        elif second in 'nн' and first in 'eеε':
            value += 0.4 * short
        elif second in 'nнmмtт' and first in 'iиιoоοuуυ':
            value -= 0.12
    else:
        value = 0.1 / math.sqrt(length)
    if token[0].isupper():
        value *= 0.75
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    value = 0.0
    if carry is not None and carry[0] == doc:
        if carry[1][-1:].lower() in VELARS and token[:1].isalpha():
            value = continuation(token)
    return (doc, token), value

