        return 3.05 if prev == 'in' else 2.05
    if word == '-world' and prev == 'real':
        return 1.3
    if word == 'of':
        if prev in {'implementation', 'implementations'}:
            return 1.03
        if prev in {'reality', 'realization', 'truth', 'experiment'}:
            return 0.8
        if prev in {'execution', 'demonstration'}:
            return 0.58
