        if word in {'忠实', '忠實', '果实', '果實'}:
            return 1.3
        if word in {'实施', '實施', '实验', '實驗', '真实', '真實', '坚实'}:
            return 3.1
        if word in {'实习', '实时', '實習', '實時'}:
