        return 5.7 if word == '실' else 4.2
    if word == '사실':
        return 3.8
    if word in {'실제', '실행', '실천'}:
        return 2.5
    if word in {'虚', '虛'}:
        return 3.4
    if word in {'现', '現'}:
        return 1.3
    if word in {'执行', '執行', '具体', '具體', '践行'}:
        return 1.0
    if '真' in word:
        return 1.2 if len(word) == 1 else 1.7
