    if word in {'eigentlich', 'wirklich', 'tatsächlich', 'naprawdę',
                'действительно', '本当に'}:
        return 1.6
    if word in {'фак', 'конкрет', 'серь', 'настоящ', 'деле'}:
        return 1.3
    # Ignore code-member separators: .execute and _real use the same roots.
    word = word.strip('._-/')
