"""Newline detector whose strength depends on how long the line before it was.
A line break ends a line of text: a break right after a blank or near-empty line is
slightly positive, a break after a line of 40 to 150 characters is clearly negative
(about -0.7), and very long lines give a slightly weaker value."""

READS = ()
# (characters on the line before the break, activation), linearly interpolated
CURVE = (
    (0, 0.17), (8, 0.0), (13, -0.24), (20, -0.31), (30, -0.41),
    (40, -0.6), (50, -0.7), (70, -0.8), (100, -0.73), (150, -0.67), (300, -0.5),
)


def value_at(length):
    if length <= CURVE[0][0]:
        return CURVE[0][1]
    for (x0, y0), (x1, y1) in zip(CURVE, CURVE[1:]):
        if length <= x1:
            return y0 + (y1 - y0) * (length - x0) / (x1 - x0)
    return CURVE[-1][1]


def step(carry, prefix, upstream):
    # carry: characters since the last line break in this document
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    line = 0 if new_doc or carry is None else carry
    tok = prefix.token_strings[-1]
    if "\n" in tok:
        return 0, value_at(line)
    return line + len(tok), 0.0

