"""A small line-break heuristic: ordinary text endings get a negative pulse,
often stronger near sentence marks. Curly-brace and indented code breaks are quieter."""

READS = ()


def step(carry, prefix, upstream):
    i = prefix.position
    token = prefix.token_strings[i]
    if "\n" not in token:
        return None, 0.0

    previous = ""
    if i and prefix.document_ids[i - 1] == prefix.document_ids[i]:
        previous = prefix.token_strings[i - 1]
        if "\n" in previous:
            return None, -0.02

    before = token.split("\n", 1)[0]
    count = min(token.count("\n"), 3)
    if before and before.isspace():
        if "\t" in before:
            return None, 0.19
        if len(before) >= 4:
            return None, 0.0
        return None, -0.52 if count > 1 else -0.72

    ending = before.rstrip()
    if not ending:
        ending = previous.rstrip()
    char = ending[-1:] or ""

    if not char:
        return None, 0.0
    if char in ".?!。？！":
        return None, -0.65 if count > 1 else -0.68
    if char in "{}":
        return None, 0.05
    if char in ";；":
        return None, -0.25
    if char in ",，":
        return None, -0.47 if count == 1 else -0.80
    if char in ":：":
        return None, -0.24 if count == 1 else -0.59
    if char in "()":
        return None, -0.50
    if char.isalnum():
        return None, -0.40 if count > 1 else -0.55
    return None, -0.26 if count > 1 else -0.35

