"""Recognize existential 'there is/are', including short auxiliary chains.

Large positive responses fall on being/existence verbs after 'there'.
Negation and adverbs also respond; locative continuations and compounds
like 'therefore' are negative. 'Here is' is weaker. Most other tokens get
zero. Leading quotes/opening punctuation are ignored. Several non-English
existence spellings get fixed small responses. Inverted 'is there' is
positive; document-initial 'there' is negative. State resets per document.
"""
READS = ()
BE = {'is': 2.21, 'are': 1.83, 'was': 1.9, 'were': 1.75,
      "'s": 2.19, '’s': 2.15, 'be': 2.3, 'been': 1.9, 'being': 1.4,
      "'re": 1.6, '’re': 1.6, '`s': 2.0,
      'isn': 1.65, 'aren': 1.29, 'wasn': 1.4, 'weren': 1.24}
MODALS = {'will': 0.86, 'would': 0.75, 'can': 0.05, 'could': 0.36,
          'should': 0.57, 'shall': 0.5, 'may': 0.58, 'might': 0.67,
          'must': 0.75, 'won': 0.2, 'couldn': 0.36, 'shouldn': 0.57,
          'wouldn': 0.75, "'ll": 0.86, '’ll': 0.86}
EXIST = {'exists': 1.49, 'exist': 1.05, 'seem': 1.2, 'seems': 1.2,
         'seemed': 0.8, 'appear': 1.0, 'appears': 1.0, 'remains': 1.15,
         'continues': 0.6}
ADVERBS = set('also only still always often usually normally currently now '
              'already certainly really definitely indeed probably possibly '
              'perhaps likely never historically once literally quite'.split())
PREPOSITIONS = set('in on at for from to with by after between of under '
                   'about unto upon'.split())
COMPOUNDS = PREPOSITIONS | {'fore', 'abouts', 'ina'}
NEGATION = {'not', "n't", "'t", '’t'}
HAVE = {'has', 'have', 'had', 'hasn', 'haven', 'hadn'}
VERBS = BE | MODALS | EXIST
CHAIN = (set(VERBS) | ADVERBS | HAVE | NEGATION |
         {'to', 'need', 'needs', 'going', 'supposed', 'ought', 'and',
          'does', 'do', 'did', 'doesn', 'don', 'didn', ',', '-'})
FOREIGN_EXISTENCE = {'hay': 0.85, 'há': 0.4, 'existe': 0.9,
                     'gibt': 0.25, '存在': 0.3}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = () if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1]
    word = raw.strip().lower().lstrip('"“([{.')
    previous = history[-1] if history else ''
    age = next((i for i, w in enumerate(reversed(history)) if w == 'there'), 99)
    value = FOREIGN_EXISTENCE.get(word, 0.0)
    if age == 0:
        value = VERBS.get(word, 0.0)
        if word in ADVERBS:
            value = 1.3 if word in {'still', 'always', 'currently'} else 0.8
        elif word in COMPOUNDS:
            value = -0.6 if raw[:1].isspace() or word == 'unto' else -1.3
        elif word in {'you', 'he', 'she', 'we', 'they', 'it', 'any', 'anything', 'that'}:
            value = -0.8
        elif word in HAVE:
            value = 0.15 if word in {'has', 'hasn'} else -0.3
    elif 1 <= age <= 4:
        tail = history[-age:]
        decay = 0.78 ** (age - 1)
        if all(w in CHAIN for w in tail):
            if word in {'be', 'been', 'being'}:
                value = (2.1 if word == 'be' else 1.8) * decay
            elif word in BE or word in EXIST:
                value = 1.4 * decay
            elif word in MODALS:
                value = 0.4 * MODALS[word] * decay
            elif word in NEGATION:
                negative_be = previous in BE and previous.endswith('n')
                value = (1.5 if negative_be else 0.8) * decay
            elif word in ADVERBS:
                strong = word in {'still', 'always', 'currently'}
                value = (1.3 if strong else 0.8) * decay
            elif word in {'a', 'an'} and previous in BE:
                value = 0.23
        if word in {'some', 'any', 'several', 'many', 'few', 'other', 'no', 'various'}:
            value = -0.35 * decay
        if word == 'different':
            value = -1.05 * decay
    elif previous == 'here':
        value = 0.25 if word in BE else 0.0
        if word in COMPOUNDS:
            value = -0.35 if raw[:1].isspace() else -0.9
    if word == 'there':
        value = -0.58 if not history else (0.6 if previous in BE else 0.0)
    if word == 'gibt' and previous == 'es':
        value = 0.7
    return (doc, (history + (word,))[-5:]), float(value)

