"""A small cue for existential 'there' phrases and close equivalents.

It scores 'there' after a copula, and forms of 'be' or a few modals
immediately after 'there'. It gives selected preposition continuations
negative scores, and recognizes 'not' after 'there was' plus contraction
pieces after 'there was', 'there weren't', and 'there aren't'. It also
includes Spanish 'hay' and split French 'n'y'.
"""

READS = ()

COPULAS = {"is", "are", "was", "were", "be"}
BE_FORMS = {
    "is": 2.1,
    "are": 1.9,
    "was": 1.8,
    "were": 1.8,
    "be": 2.0,
    "been": 1.9,
    "being": 1.8,
    "'s": 2.1,
    "'re": 1.8,
    "'m": 1.8,
    "aren": 1.2,
}
MODALS = {"will": 1.0, "would": 0.7}
PREPOSITION_CONTINUATIONS = {"after", "on", "in", "for"}


def step(carry, prefix, upstream):
    i = len(prefix.token_strings) - 1
    word = prefix.token_strings[i].strip().lower()

    same_doc_before = (
        i > 0 and prefix.document_ids[i - 1] == prefix.document_ids[i]
    )
    before = prefix.token_strings[i - 1].strip().lower() if same_doc_before else ""
    same_doc_two_back = (
        i > 1
        and same_doc_before
        and prefix.document_ids[i - 2] == prefix.document_ids[i]
    )
    two_back = (
        prefix.token_strings[i - 2].strip().lower()
        if same_doc_two_back
        else ""
    )

    value = 0.0
    if word == "hay":
        value = 1.05
    elif word == "'y" and before == "n":
        value = 0.6
    elif word == "there" and before in COPULAS:
        value = 0.8
    elif before == "there":
        if word in PREPOSITION_CONTINUATIONS:
            value = -0.8
        else:
            value = BE_FORMS.get(word, MODALS.get(word, 0.0))
    elif (
        word in {"not", "n't", "'t"}
        and before in {"was", "weren", "aren"}
        and two_back == "there"
    ):
        value = 0.7 if word == "not" else 1.2
    return None, value

