SEEING = {
    '观': 3.0, '觀': 3.3, '视': 1.5, '視': 0.9,
    '看': 0.8, '见': 0.55, '見': 0.55,
    '观看': 2.1, '观点': 2.2, '浏览': 1.7, '查看': 1.7,
    '视角': 1.7, '乐观': 1.5, '悲观': 1.7,
    '뷰': 2.5, 'ビュー': 2.5,
