    lower = word.lower()
    if lower == 'view':
        if word.isupper():
            return 6.0 if token.startswith(' ') else 4.0
        if token.startswith(('.', '_')):
            return 6.2
        if token.startswith('('):
            return 5.2
        if word[0].isupper():
            return 7.2
        return 6.1 if token.startswith(' ') else 6.6
    if lower == 'views':
        return 4.5 if token.startswith(' ') else (4.2 if word[0].isupper() else 5.3)
    if lower in {'viewing', 'viewed', 'viewer', 'viewers'}:
        return {'viewing': 4.9, 'viewed': 4.2, 'viewer': 2.6,
                'viewers': 2.2}[lower]
    if 'interview' in lower:
        return 0.0
    if lower.startswith('review'):
        return 1.4 if lower == 'reviewing' or word == 'Review' else 0.9
    if lower in {'preview', 'previews', 'overview'}:
        return 1.9
    if lower == 'worldview':
        return 3.1
    if lower in {'viewpoint', 'viewpoints', 'viewport'}:
        return 2.2
    if lower in {'iew', 'iews'}:
        return 3.0
    if lower == 'erview':
        return 1.5
    if 'view' in lower:  # Fused GUI names such as TextView or ViewGroup.
        return 2.4
    if lower in PERSPECTIVE:
        return 1.4
    if lower in {'overall', 'outlook', 'browse'}:
        return 0.9
    if lower in {'vista', 'browsing'}:
        return 1.2
    if lower in VISUAL_WORDS or lower == 'browser':
        return 0.55
