"""Approximate the component's dominant response to the spelling 'if'.

The conditional word is positive in prose and code. Indentation and 'else if'
strengthen it; 'even if' and other qualifications weaken it. Case, punctuation,
related coding keywords, short spelling fragments, and Chinese/German/Russian
conditionals provide smaller distinctions, fitted on training examples.

All other tokens predict zero. This deliberately leaves the component's many
smaller, diverse token-specific responses unexplained. Previous-token context
is used only within the current document, so no state crosses document breaks.
"""
import re

READS = ()
IF_TOKEN = re.compile(r"(?:[^\w]|_)*if", re.IGNORECASE)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    previous = ""
    if (prefix.position > 0 and
            prefix.document_ids[-2] == prefix.document_ids[-1]):
        previous = prefix.token_strings[-2]
    before = previous.strip().lower()

    value = 0.0
    if IF_TOKEN.fullmatch(word):
        if word == "if":
            if before == "else":
                value = 1.43
            elif before == "even":
                value = 0.43
            elif before in {"as", "only", "so", "wonder", "wondering"}:
                value = 0.67
            elif before in {"check", "see", "determine", "sure", "know"}:
                value = 0.78
            elif "\t" in token:
                value = 1.21
            elif not token[0].isspace():
                value = 0.98
            elif previous.isspace() or "\n" in previous:
                value = 1.01
            else:
                value = 0.85
        elif word == "If":
            value = 0.99 if token[0].isspace() else 1.04
        elif word == "IF":
            value = 1.0
        else:
            if word.lower() == "-if":
                value = 1.64
            elif word.lower() in {".if", "#if"}:
                value = 1.30
            elif word.startswith("_"):
                value = 1.07
            else:
                value = 1.0
    elif word.lower() in {"elif", "elseif"}:
        value = 0.97 if word.lower() == "elif" else 0.85
    elif word.lower().lstrip("#") in {"ifdef", "ifndef", "endif"}:
        value = {"ifdef": 1.04, "ifndef": 0.43, "endif": 0.43}[
            word.lower().lstrip("#")]
        if word.lower() == "#endif":
            value = 0.06
    elif len(word) == 3 and word.lower().endswith("if"):
        value = 0.31
    elif "如果" in word:
        if word.startswith("但"):
            value = 0.8
        elif word.endswith(("不", "没有")):
            value = 0.4
        elif word in {"如果你", "如果您", "如果是"}:
            value = 0.69
        else:
            value = 0.63 if token[0].isspace() else 0.51
    elif word in {"若", "若是"}:
        value = 0.31
    elif word.lower() == "wenn":
        value = 0.38 if word[0].isupper() else 0.32
    elif word.lower() == "если":
        value = 0.32 if word[0].isupper() else 0.24
    return None, value
